const indexPage = "<!doctype html>\r\n<html lang=\"es\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Radar de Mercados</title>\r\n<style>\r\n:root{color-scheme:light;--bg:#edf6f5;--p:#fff;--p2:#f4fbfa;--l:#b8d4d1;--t:#123139;--m:#54727a;--teal:#087e78;--amber:#b77900;--red:#c24157;--sh:0 10px 28px #16464c1a}html[data-theme=dark]{color-scheme:dark;--bg:#061922;--p:#0c2734;--p2:#102f3c;--l:#1a5361;--t:#ecfdf8;--m:#9bbbc2;--teal:#5eead4;--amber:#fbbf24;--red:#fb7185;--sh:0 14px 36px #0003}*{box-sizing:border-box}body{margin:0;background:radial-gradient(900px 450px at 75% -100px,#1c8b912e,transparent 62%),var(--bg);color:var(--t);font:16px Inter,system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:28px 22px 56px}.top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:18px}.ey{margin:0 0 7px;color:var(--teal);font-size:.75rem;letter-spacing:.12em;text-transform:uppercase;font-weight:800}h1{margin:0;font-size:clamp(2rem,5vw,3.2rem);letter-spacing:-.055em;line-height:1}h2,h3{margin:0}p{margin:0;color:var(--m);line-height:1.55}.sub{margin-top:12px}.actions{display:flex;gap:9px;align-items:center}.button,.stamp,.tab{border:1px solid var(--l);background:var(--p);color:var(--t);border-radius:99px;padding:10px 14px;font:inherit;font-size:.84rem;white-space:nowrap}.button,.tab{cursor:pointer}.button:hover,.tab:hover{border-color:var(--teal)}.notice{border:1px solid var(--l);border-left:4px solid var(--amber);background:var(--p2);border-radius:12px;padding:14px 16px;margin-bottom:17px}.tabs{display:flex;gap:9px;margin-bottom:17px}.tab[aria-selected=true]{background:var(--teal);border-color:var(--teal);color:#fff}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:15px}.card{min-width:0;background:var(--p);border:1px solid var(--l);border-radius:18px;padding:19px;box-shadow:var(--sh)}.s12{grid-column:span 12}.s7{grid-column:span 7}.s5{grid-column:span 5}.head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:15px}.head h2{font-size:1.04rem}.tools{display:flex;gap:7px;flex-wrap:wrap}.tools .tab{padding:8px 11px;font-size:.78rem}.radar{display:grid;grid-template-columns:minmax(200px,280px) 1fr;gap:22px;align-items:center}.num{font-size:clamp(3rem,7vw,5.3rem);font-weight:850;letter-spacing:-.07em;line-height:.9}.num small{font-size:1.1rem}.meter{height:14px;border-radius:99px;overflow:hidden;background:var(--l);margin:13px 0 9px}.meter span{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,#16a34a,#eab308 48%,#dc2626)}.traffic{display:inline-block;border:1px solid var(--l);border-radius:99px;padding:5px 8px;font-size:.73rem;font-weight:700}.green{background:#16a34a1f;color:#16733d;border-color:#16a34a66}.yellow{background:#eab30820;color:#986b00;border-color:#eab30866}.red{background:#dc26261c;color:#b32338;border-color:#dc262655}html[data-theme=dark] .green{color:#86efac}html[data-theme=dark] .yellow{color:#fde68a}html[data-theme=dark] .red{color:#fda4af}.break{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.charts{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.chart{background:var(--p2);border:1px solid var(--l);border-radius:14px;padding:14px;min-width:0}.ct{display:flex;justify-content:space-between;gap:8px;align-items:flex-start}.ct h3{font-size:.96rem}.value{font-size:1.72rem;font-weight:850;letter-spacing:-.05em;margin-top:3px}.unit{font-size:.75rem;font-weight:500;letter-spacing:0;color:var(--m);margin-left:4px}.var{font-size:.75rem;color:var(--teal);font-weight:700;margin-top:3px;text-align:right}.note{font-size:.72rem;margin:5px 0 8px}.plot{height:158px;position:relative;cursor:crosshair}.plot svg{width:100%;height:100%;display:block;overflow:visible}.ax{fill:var(--m);font-size:9px}.line{stroke:var(--l)}.cursor{position:absolute;top:0;bottom:0;width:1px;background:var(--t);opacity:.5}.tip{position:absolute;top:4px;transform:translateX(-50%);background:var(--t);color:var(--p);padding:5px 7px;border-radius:6px;font-size:.71rem;white-space:nowrap;font-weight:700;z-index:2}.foot{display:flex;justify-content:space-between;color:var(--m);font-size:.7rem;margin-top:3px}.signals{width:100%;border-collapse:collapse;font-size:.87rem}.signals th,.signals td{text-align:left;padding:10px 7px;border-bottom:1px solid var(--l);vertical-align:top}.signals th{font-size:.7rem;text-transform:uppercase;letter-spacing:.08em;color:var(--m)}.dot{width:8px;height:8px;border-radius:50%;display:inline-block;margin-right:7px;background:var(--teal)}.dot.yellow{background:var(--amber)}.dot.red{background:var(--red)}.footer{font-size:.75rem;margin-top:16px}.guide{max-width:1000px;margin:auto}.guide[hidden],.dashboard[hidden]{display:none}.guide .card{margin-bottom:16px;padding:24px}.guide h2{font-size:1.35rem;margin-bottom:10px}.guide h3{font-size:1rem;margin:18px 0 7px}.guide p,.guide li{color:var(--m);line-height:1.65}.guide ul,.guide ol{padding-left:21px}.flow{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:17px 0}.flow span{background:var(--p2);border:1px solid var(--l);padding:10px;border-radius:10px;font-size:.86rem;font-weight:700}.flow i{font-style:normal;color:var(--teal);font-weight:900}.callout{border-left:4px solid var(--teal);background:var(--p2);padding:12px 14px;border-radius:8px;margin-top:14px}.guide a{color:var(--teal);font-weight:700}@media(max-width:900px){.s7,.s5{grid-column:span 6}.charts{grid-template-columns:repeat(2,1fr)}.radar{grid-template-columns:1fr}.top{display:block}.actions{margin-top:16px}}@media(max-width:620px){main{padding:20px 14px 44px}.s7,.s5{grid-column:span 12}.charts{grid-template-columns:1fr}.head{display:block}.tools{margin-top:12px}.actions{flex-wrap:wrap}.signals{font-size:.78rem}.signals th,.signals td{padding:8px 4px}}\r\n.gauge{width:250px;height:132px;position:relative;overflow:hidden;margin:auto}.gauge-ring{position:absolute;width:250px;height:250px;border-radius:50%;background:conic-gradient(from 270deg,#16a34a 0deg,#eab308 90deg,#dc2626 180deg,transparent 180deg);left:0;top:7px}.gauge-ring:after{content:\"\";position:absolute;inset:23px;border-radius:50%;background:var(--p)}.needle{position:absolute;width:3px;height:93px;background:var(--t);left:124px;bottom:0;transform-origin:bottom;transform:rotate(-90deg);z-index:2;border-radius:5px}.needle:after{content:\"\";position:absolute;width:13px;height:13px;border-radius:50%;background:var(--t);bottom:-5px;left:-5px}.gauge-labels{position:absolute;bottom:0;left:0;right:0;display:flex;justify-content:space-between;font-size:.75rem;color:var(--m);font-weight:700}.gauge-caption{text-align:center;font-size:.82rem;font-weight:800;color:var(--t);margin-top:2px}.guide .card{padding:28px}.guide h2{font-size:1.45rem;margin-bottom:13px}.guide h3{font-size:1.12rem;margin:22px 0 9px}.guide p,.guide li{color:var(--t);font-size:1.04rem;line-height:1.75;text-align:justify}.guide li{margin:7px 0}.flow span{font-size:.95rem}.callout{padding:14px 16px;color:var(--t);font-size:1.03rem;line-height:1.65}\r\n.fact{display:block;margin-top:5px;padding:4px 7px;border:1px solid var(--l);border-radius:7px;background:transparent;color:var(--teal);font:700 .72rem Inter,system-ui,sans-serif;cursor:pointer}.fact:hover{background:var(--p)}dialog{max-width:680px;width:calc(100% - 32px);border:1px solid var(--l);background:var(--p);color:var(--t);border-radius:18px;padding:24px;box-shadow:0 22px 70px #0008}dialog::backdrop{background:#001a2299}.dialog-close{float:right;border:1px solid var(--l);background:var(--p2);color:var(--t);border-radius:8px;padding:6px 9px;cursor:pointer}.dialog-body{margin-top:18px}.dialog-body h2{margin-bottom:10px}.dialog-body p{font-size:1rem;color:var(--t);margin:9px 0;line-height:1.65}.dialog-body b{color:var(--teal)}\r\n.gauge-value{position:absolute;z-index:3;left:0;right:0;bottom:27px;text-align:center;font-size:2.05rem;font-weight:850;letter-spacing:-.06em;color:var(--t)}.gauge-value small{font-size:.85rem;letter-spacing:0}.gauge-scale span{position:absolute;z-index:4;font-size:.76rem;font-weight:850;color:var(--t);background:var(--p);border-radius:6px;padding:1px 4px}.gauge-scale .m0{left:0;bottom:20px;color:#087e78}.gauge-scale .m25{left:42px;top:73px}.gauge-scale .m50{left:114px;top:43px}.gauge-scale .m75{right:39px;top:73px}.gauge-scale .m100{right:0;bottom:20px;color:#c24157}\r\n</style></head><body><main>\r\n<header class=\"top\"><div><p class=\"ey\">Seguimiento personal</p><h1>Radar de Mercados</h1><p class=\"sub\">Señales que ayudan a entender el entorno, no a predecirlo.</p></div><div class=\"actions\"><a href=\"consultor.html\" class=\"button\">Consultor de activos</a><button id=\"theme\" class=\"button\">Usar fondo oscuro</button><div id=\"updated\" class=\"stamp\">Cargando datos…</div></div></header>\r\n<div class=\"notice\"><b>● &nbsp; Lectura, no predicción.</b> Una señal aislada no confirma una crisis. Busca movimientos simultáneos y persistentes.</div>\r\n<nav class=\"tabs\"><button class=\"tab view\" data-view=\"dash\" aria-selected=\"true\">Tablero</button><button class=\"tab view\" data-view=\"guide\" aria-selected=\"false\">Cómo leer el radar</button></nav>\r\n<section id=\"dash\" class=\"dashboard grid\">\r\n<article class=\"card s12\"><div class=\"radar\"><div><p class=\"ey\">Radar de atención</p><div class=\"gauge\" aria-label=\"Medidor de atención de 0 a 100\"><div class=\"gauge-ring\"></div><i id=\"needle\" class=\"needle\"></i><div id=\"score\" class=\"gauge-value\">—<small>/100</small></div><div class=\"gauge-scale\"><span class=\"m0\">0</span><span class=\"m25\">25</span><span class=\"m50\">50</span><span class=\"m75\">75</span><span class=\"m100\">100</span></div></div><p id=\"level\" class=\"gauge-caption\">Calculando la lectura conjunta…</p></div><div><h2 id=\"rtitle\">Lectura de conjunto</h2><p id=\"rtext\" style=\"margin-top:6px\">Se evalúan crédito, volatilidad, liquidez, tasas, energía, inflación y empleo con reglas visibles y educativas.</p><div class=\"break\" id=\"break\"></div></div></div></article>\r\n<article class=\"card s12\"><div class=\"head\"><div><h2>Lectura y tendencia por indicador</h2><p>Cada tarjeta reúne el valor actual, su semáforo, su variación y el gráfico. Pasa el ratón sobre una línea para leer fecha y valor.</p></div><div class=\"tools\"><button class=\"tab period\" data-range=\"daily\" aria-selected=\"true\">Diario</button><button class=\"tab period\" data-range=\"weekly\">Semanal</button><button class=\"tab period\" data-range=\"monthly\">Mensual</button><button class=\"tab period\" data-range=\"year\">1 año</button></div></div><div id=\"charts\" class=\"charts\">Cargando indicadores…</div></article>\r\n<article class=\"card s7\"><div class=\"head\"><div><h2>Señales a vigilar</h2><p>Resumen de las señales y qué significa cada grupo.</p></div></div><table class=\"signals\"><thead><tr><th>Señal</th><th>Lectura</th><th>Por qué importa</th></tr></thead><tbody id=\"rows\"></tbody></table></article>\r\n<article class=\"card s5\"><h2>Cómo usarlo sin perder el contexto</h2><p style=\"margin-top:9px\">El semáforo resume reglas sencillas; el gráfico aporta el contexto. Un cambio rápido importa más cuando otras señales apuntan en la misma dirección.</p><p style=\"margin-top:12px\">La pestaña <b>Cómo leer el radar</b> explica cada indicador, sus límites y por qué el marcador global no es una recomendación de compra o venta.</p></article>\r\n</section>\r\n<section id=\"guide\" class=\"guide\" hidden>\r\n<article class=\"card\"><p class=\"ey\">Guía del tablero</p><h2>Cómo leer el radar de mercados</h2><p>Este tablero reúne datos públicos para ayudarte a ordenar preguntas, no para adivinar el futuro. La economía rara vez se mueve por una sola causa: costes, inflación, tasas, crédito, liquidez y expectativas se influyen entre sí y lo hacen con retrasos distintos.</p><div class=\"callout\"><b>Idea central:</b> observa la dirección, la velocidad y la coincidencia entre indicadores. El número de hoy, por sí solo, no basta.</div></article>\r\n<article class=\"card\"><h2>1. La economía como un circuito</h2><p>Una manera sencilla de pensar el tablero es seguir esta cadena. No es una ley automática: es una guía para ordenar lo que puede estar ocurriendo.</p><div class=\"flow\"><span>Costes de energía y transporte</span><i>→</i><span>Precios e inflación</span><i>→</i><span>Tasas y coste del crédito</span><i>→</i><span>Consumo, inversión y riesgo</span></div><h3>Diésel e inflación</h3><p>El diésel es un coste de transporte, agricultura, logística y producción. Si sube con rapidez, puede encarecer llevar personas y mercancías. Eso puede añadir presión a algunos precios, aunque no significa que toda subida del diésel se convierta automáticamente en inflación general.</p><h3>Inflación CPI anual</h3><p>El tablero muestra el cambio porcentual anual del índice de precios al consumidor (CPI): compara el nivel de precios actual con el mismo mes del año anterior. Una inflación persistente puede llevar a condiciones financieras más restrictivas; los efectos sobre hogares y empresas no son inmediatos ni iguales para todos.</p><h3>Treasury a 10 años</h3><p>El rendimiento del bono del Tesoro estadounidense a 10 años refleja, entre otras cosas, expectativas de inflación, crecimiento y la compensación que pide el mercado por prestar a largo plazo. No es exactamente la tasa que fija la Reserva Federal, pero puede influir en hipotecas, financiación empresarial y valoración de activos.</p></article>\r\n<article class=\"card\"><h2>2. Riesgo, protección y crédito</h2><h3>VIX: volatilidad esperada, no una bola de cristal</h3><p>El VIX se calcula a partir de precios de opciones del S&amp;P 500 y resume la volatilidad esperada a corto plazo que está implícita en ese mercado. Cuando la protección mediante opciones se encarece, el VIX suele subir. No quiere decir simplemente que “la gente compra VIX”; es un índice construido con precios de muchas opciones. Una lectura alta indica que el mercado está pagando más por protección, no que una caída esté garantizada.</p><h3>High Yield OAS: prima por riesgo de crédito</h3><p>El diferencial High Yield OAS compara los rendimientos de bonos corporativos de mayor riesgo con una referencia de menor riesgo. Cuando se amplía, suele indicar que los inversionistas exigen más compensación por riesgo de crédito. Conviene mirarlo junto al VIX: si ambos suben y se mantienen elevados, la cautela del mercado es más amplia.</p><div class=\"callout\"><b>Ejemplo:</b> VIX alto durante un día puede responder a una noticia. VIX alto más crédito deteriorándose durante semanas cuenta una historia más seria, pero aun así no confirma un desenlace.</div></article>\r\n<article class=\"card\"><h2>3. Liquidez: RRP, TGA y reservas</h2><p>Estas tres lecturas describen partes diferentes de la “plomería” financiera de Estados Unidos. No deben interpretarse como un interruptor único de liquidez.</p><ul><li><b>RRP overnight:</b> acuerdos de recompra inversa a un día. Es una facilidad de la Reserva Federal mediante la cual ciertas contrapartes pueden colocar efectivo temporalmente.</li><li><b>TGA · cuenta del Tesoro:</b> Treasury General Account, la cuenta operativa del Tesoro de EE. UU. Cuando cambia, puede afectar transitoriamente dónde está el efectivo dentro del sistema.</li><li><b>Reservas bancarias:</b> saldos que las instituciones depositarias mantienen en la Reserva Federal. Son una medida importante, pero no una medición completa de todo el crédito o la liquidez global.</li></ul><p>Las tres se muestran en <b>miles de millones de USD</b>, para evitar cifras largas difíciles de leer.</p></article>\r\n<article class=\"card\"><h2>4. Semáforos y radar de atención</h2><p>Cada tarjeta recibe una luz verde, amarilla o roja con una explicación corta. Son umbrales didácticos, visibles y modificables; no son un sistema de inversión ni una alerta de crisis.</p><ul><li><b>Crédito: 25%.</b> Los diferenciales de crédito suelen resumir bien la disposición a asumir riesgo.</li><li><b>VIX: 20%.</b> Aporta la percepción de volatilidad esperada del mercado de acciones.</li><li><b>Liquidez: 20%.</b> Combina RRP, TGA y reservas para evitar depender de una sola cifra.</li><li><b>Treasury 10 años: 15%.</b> Da contexto sobre condiciones financieras de largo plazo.</li><li><b>Diésel: 10%.</b> Vigila movimientos rápidos de un coste físico relevante.</li><li><b>Inflación: 10%.</b> Añade el contexto de precios sin duplicar el mismo mensaje varias veces.</li></ul><p>De 0 a 29 se muestra “entorno tranquilo”; de 30 a 59, “atención”; de 60 a 100, “tensión elevada”. Es una forma de priorizar qué mirar, no una predicción ni una orden de actuar.</p><h3>Rutina práctica</h3><ol><li>Mira el marcador general y cuáles son los contribuyentes principales.</li><li>Revisa las tarjetas amarillas o rojas y el periodo de tiempo.</li><li>Pasa el ratón sobre el gráfico para comprobar la fecha y el valor.</li><li>Busca coincidencias: crédito, VIX y liquidez juntos suelen ser más informativos que una sola serie.</li></ol></article>\r\n<article class=\"card\"><h2>Fuentes y frecuencia</h2><p>Los datos llegan de FRED, que publica series de organismos como la Reserva Federal, el Tesoro, BLS y Cboe. Algunas series son diarias, otras semanales o mensuales; por eso los botones de periodo no convierten una serie mensual en una diaria.</p><ul><li><a href=\"https://fred.stlouisfed.org/series/VIXCLS\" target=\"_blank\" rel=\"noopener\">VIX en FRED</a> y <a href=\"https://www.cboe.com/tradable-products/vix/\" target=\"_blank\" rel=\"noopener\">descripción de Cboe</a>.</li><li><a href=\"https://fred.stlouisfed.org/series/CPIAUCSL\" target=\"_blank\" rel=\"noopener\">CPI en FRED</a>.</li><li><a href=\"https://home.treasury.gov/policy-issues/financing-the-government/interest-rate-statistics\" target=\"_blank\" rel=\"noopener\">tasas del Tesoro</a> y <a href=\"https://www.federalreserve.gov/faqs/why-do-interest-rates-matter.htm\" target=\"_blank\" rel=\"noopener\">por qué importan las tasas</a>.</li></ul></article>\r\n<article class=\"card\"><h2>Instituciones y fuentes: quién hace qué</h2><p><b>Reserva Federal (Fed):</b> influye en las condiciones monetarias y supervisa partes del sistema bancario. El presidente de su Junta de Gobernadores y del FOMC es Kevin Warsh, según la consulta oficial del 2 de octubre de 2026.</p><p><b>Departamento del Tesoro:</b> administra las finanzas del gobierno federal y la cuenta TGA. Su secretario es Scott Bessent.</p><p><b>BLS:</b> publica empleo, inflación CPI, salarios y productividad; no decide las tasas. Su comisionado es Brett Matsumoto.</p><p><b>BEA:</b> publica PIB, consumo, ingresos y otras cuentas nacionales. Su director es Vipin Arora.</p><p><b>EIA:</b> publica estadísticas energéticas como el diésel. <b>Cboe:</b> produce la metodología del VIX; no es un organismo gubernamental. <b>Fed de Chicago:</b> publica el NFCI y forma parte del sistema de la Reserva Federal; su presidente es Austan Goolsbee.</p><div class=\"callout\"><b>Nota de actualización:</b> los cargos pueden cambiar. Esta ficha muestra responsables consultados el 2 de octubre de 2026.</div></article></section><p class=\"footer\">Datos públicos con posible retraso según la fuente. Este tablero es educativo y no es asesoramiento financiero ni una instrucción de compra o venta.</p></main><dialog id=\"factDialog\"><button class=\"dialog-close\" id=\"closeFact\">Cerrar</button><div class=\"dialog-body\" id=\"factBody\"></div></dialog>\r\n<script>\r\nconst $=x=>document.getElementById(x);let market,range='daily';const C={vix:'#a855f7',credit:'#0f9c92',treasury10y:'#2563eb',diesel:'#d97706',rrp:'#7c3aed',tga:'#e11d48',reserves:'#059669',inflation:'#dc2626',claims:'#6d28d9'};const M={vix:['Índice de volatilidad (VIX)','puntos'],credit:['Diferencial de bonos de alto rendimiento (High Yield OAS)','%'],treasury10y:['Bono del Tesoro a 10 años (Treasury 10Y)','%'],diesel:['Diésel minorista de EE. UU.','USD/gal'],rrp:['Acuerdos de recompra inversa a un día (RRP)','mil millones USD'],tga:['Cuenta General del Tesoro (TGA)','mil millones USD'],reserves:['Reservas bancarias (Bank Reserves)','mil millones USD'],inflation:['Inflación anual de precios (CPI)','%'],claims:['Solicitudes iniciales de desempleo (Initial Claims)','miles de solicitudes']};\r\nfunction theme(x){document.documentElement.dataset.theme=x;localStorage.setItem('radar-theme',x);$('theme').textContent=x==='light'?'Usar fondo oscuro':'Usar fondo claro'}theme(localStorage.getItem('radar-theme')||'light');$('theme').onclick=()=>theme(document.documentElement.dataset.theme==='light'?'dark':'light');\r\nfunction prep(k,a){let p=(a||[]).map(x=>({date:x.date,value:+x.value})).filter(x=>Number.isFinite(x.value));if(k==='inflation')p=p.slice(12).map((x,i)=>({date:x.date,value:(x.value/p[i].value-1)*100}));if(k==='tga'||k==='reserves'||k==='claims')p=p.map(x=>({date:x.date,value:x.value/1000}));return p}function pick(k,p){return p.slice(-({daily:k==='inflation'?12:30,weekly:k==='inflation'?18:52,monthly:k==='inflation'?24:120,year:k==='inflation'?60:252}[range]))}function f(v,k){return!Number.isFinite(v)?'—':(['rrp','tga','reserves','claims'].includes(k)?v.toFixed(v<10?2:0):v.toFixed(2))}function ch(p,n=1){let b=p[Math.max(0,p.length-1-n)]?.value;return b?(p.at(-1).value/b-1)*100:0}\r\nfunction state(k,a){let p=prep(k,a),v=p.at(-1)?.value||0,s=20,r='Lectura estable';if(k==='vix'){s=v>=30?85:v>=20?52:16;r=v>=30?'Volatilidad esperada elevada':v>=20?'Volatilidad por vigilar':'Volatilidad contenida'}if(k==='credit'){s=v>=5?85:v>=4?55:17;r=v>=5?'Prima por riesgo alta':v>=4?'Prima por riesgo ampliada':'Sin tensión destacada'}if(k==='treasury10y'){s=v>=5?68:v>=4.5?42:20;r=v>=5?'Rendimiento elevado':v>=4.5?'Tasas de largo plazo altas':'Nivel moderado'}if(k==='inflation'){s=v>=4?75:v>=3?48:18;r=v>=4?'Inflación anual elevada':v>=3?'Inflación por vigilar':'Inflación moderada'}if(k==='claims'){s=v>=320?75:v>=260?45:18;r=v>=320?'Solicitudes de empleo elevadas':v>=260?'Mercado laboral por vigilar':'Mercado laboral estable'}if(k==='diesel'){let q=Math.abs(ch(p,4));s=q>=15?78:q>=7?48:18;r=q>=15?'Movimiento rápido de energía':q>=7?'Energía con cambio notable':'Energía relativamente estable'}if(['rrp','tga','reserves'].includes(k)){let q=Math.abs(ch(p,4));s=q>=12?65:q>=6?40:18;r=q>=12?'Cambio notable de liquidez':q>=6?'Liquidez en movimiento':'Liquidez sin cambio brusco'}let t=s>=60?'red':s>=30?'yellow':'green';return{s,t,label:t==='red'?'Atención elevada':t==='yellow'?'Atención':'Tranquilo',r}}\r\nfunction chart(k){let raw=market.series?.[k]?.points||[],p=pick(k,prep(k,raw)),[name,u]=M[k],z=state(k,raw);if(!p.length)return'';let vs=p.map(x=>x.value),lo=Math.min(...vs),hi=Math.max(...vs),sp=hi-lo||1,w=440,h=158,x=i=>34+i*402/Math.max(1,p.length-1),y=v=>140-(v-lo)*118/sp,d=p.map((q,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(q.value).toFixed(1)).join(' '),v=p.at(-1).value,dlt=v-(p.at(-2)?.value??v),e=encodeURIComponent(JSON.stringify(p));return `<article class=\"chart\"><div class=\"ct\"><div><h3>${name}</h3><div class=\"value\">${f(v,k)}<span class=\"unit\">${u}</span></div></div><div><span class=\"traffic ${z.t}\">${z.label}</span><div class=\"var\">${dlt>=0?'+':''}${f(dlt,k)} vs. anterior</div></div></div><p class=\"note\">${z.r}</p><div class=\"plot\" data-k=\"${k}\" data-u=\"${u}\" data-p=\"${e}\"><svg viewBox=\"0 0 ${w} ${h}\" preserveAspectRatio=\"none\"><line class=\"line\" x1=\"34\" x2=\"436\" y1=\"22\" y2=\"22\"/><line class=\"line\" x1=\"34\" x2=\"436\" y1=\"79\" y2=\"79\"/><line class=\"line\" x1=\"34\" x2=\"436\" y1=\"140\" y2=\"140\"/><text class=\"ax\" x=\"0\" y=\"25\">${f(hi,k)}</text><text class=\"ax\" x=\"0\" y=\"82\">${f((hi+lo)/2,k)}</text><text class=\"ax\" x=\"0\" y=\"143\">${f(lo,k)}</text><path d=\"${d} L436 140 L34 140Z\" fill=\"${C[k]}\" opacity=\".13\"/><path d=\"${d}\" fill=\"none\" stroke=\"${C[k]}\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg><i class=\"cursor\" hidden></i><span class=\"tip\" hidden></span></div><div class=\"foot\"><span>${p[0].date}</span><span>${u}</span><span>${p.at(-1).date}</span></div></article>`}\r\nfunction hover(){document.querySelectorAll('.plot').forEach(q=>{let p=JSON.parse(decodeURIComponent(q.dataset.p)),u=q.dataset.u,k=q.dataset.k,c=q.querySelector('.cursor'),t=q.querySelector('.tip');q.onpointermove=e=>{let r=q.getBoundingClientRect(),n=Math.round(Math.max(0,Math.min(1,(e.clientX-r.left)/r.width))*(p.length-1)),x=n/(p.length-1)*100;c.style.left=x+'%';t.style.left=x+'%';t.textContent=`${p[n].date}: ${f(p[n].value,k)} ${u}`;c.hidden=t.hidden=false};q.onpointerleave=()=>c.hidden=t.hidden=true})}\r\nfunction overall(){let S=k=>state(k,market.series?.[k]?.points||[]).s,L=(S('rrp')+S('tga')+S('reserves'))/3,n=Math.round(S('credit')*.22+S('vix')*.18+L*.18+S('treasury10y')*.14+S('diesel')*.08+S('inflation')*.10+S('claims')*.10),a=['vix','credit','treasury10y','diesel','rrp','tga','reserves','inflation','claims'].map(k=>[k,state(k,market.series?.[k]?.points||[])]),c={green:0,yellow:0,red:0};a.forEach(x=>c[x[1].t]++);let title=n>=60?'Tensión elevada':n>=30?'Atención':'Entorno tranquilo',top=a.sort((x,y)=>y[1].s-x[1].s).slice(0,2).map(x=>M[x[0]][0]).join(' y ');$('needle').style.transform=`rotate(${-90+n*1.8}deg)`;$('level').textContent=title;$('rtitle').textContent=title;$('rtext').textContent=`Los aportes que más requieren contexto ahora son ${top}. El resultado ayuda a priorizar la lectura; no predice mercados.`;$('break').innerHTML=`<span class=\"traffic green\">${c.green} tranquilo${c.green===1?'':'s'}</span><span class=\"traffic yellow\">${c.yellow} en atención</span><span class=\"traffic red\">${c.red} con atención elevada</span>`}\r\nfunction rows(){let a=[['VIX','vix','Mide volatilidad esperada implícita en opciones del S&P 500.'],['High Yield OAS','credit','Un diferencial que se amplía refleja una mayor prima por riesgo.'],['Treasury 10 años','treasury10y','Da contexto sobre condiciones financieras de largo plazo.'],['Inflación CPI anual','inflation','Mide el cambio de precios frente al mismo mes del año previo.'],['Diésel','diesel','Coste relevante para transporte, logística y producción.'],['RRP overnight','rrp','Muestra una facilidad de efectivo a un día de la Reserva Federal.'],['TGA · cuenta del Tesoro','tga','Es la cuenta operativa del Tesoro estadounidense.'],['Reservas bancarias','reserves','Saldos que instituciones mantienen en la Reserva Federal.'],['Solicitudes de desempleo','claims','Señal semanal temprana de cambios en el mercado laboral.']];$('rows').innerHTML=a.map(x=>{let z=state(x[1],market.series?.[x[1]]?.points||[]);return `<tr><td><span class=\"dot ${z.t==='green'?'':z.t}\"></span><b>${x[0]}</b></td><td>${z.r}</td><td>${x[2]}</td></tr>`}).join('')}\r\nfunction draw(){if(!market)return;$('charts').innerHTML=['vix','credit','treasury10y','inflation','diesel','rrp','tga','reserves','claims'].map(chart).join('');overall();rows();hover()}async function get(){let urls=['data/market.json?updated='+Date.now(),'https://raw.githubusercontent.com/aplicacioneserusalver1188-bot/radar-de-mercados/main/data/market.json'],e;for(let u of urls)try{let r=await fetch(u,{cache:'no-store'});if(!r.ok)throw Error(r.status);return await r.json()}catch(x){e=x}throw e}async function load(){try{market=await get();$('updated').textContent='Datos actualizados: '+new Intl.DateTimeFormat('es-VE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(market.updated_at));draw()}catch(e){$('updated').textContent='No se pudieron cargar los datos públicos';$('charts').textContent='No se pudieron cargar los datos públicos. Intenta actualizar la página en unos segundos.'}}document.querySelectorAll('.period').forEach(b=>b.onclick=()=>{range=b.dataset.range;document.querySelectorAll('.period').forEach(x=>x.setAttribute('aria-selected',x===b));draw()});document.querySelectorAll('.view').forEach(b=>b.onclick=()=>{let g=b.dataset.view==='guide';$('guide').hidden=!g;$('dash').hidden=g;document.querySelectorAll('.view').forEach(x=>x.setAttribute('aria-selected',x===b));scrollTo({top:0,behavior:'smooth'})});load();\r\n</script><script>\r\nconst fichas={\r\nvix:{t:'Índice de volatilidad (Volatility Index, VIX)',q:'Mide la volatilidad esperada del S&P 500 durante los próximos 30 días, a partir de precios de opciones.',u:'Suele subir cuando aumenta el coste de protegerse ante movimientos bruscos del mercado. No predice por sí solo una caída.',f:'Cboe; disponible diariamente en FRED.'},\r\ncredit:{t:'Diferencial de bonos de alto rendimiento (High Yield OAS)',q:'Es la prima adicional que exigen los inversionistas para prestar a empresas de mayor riesgo frente a una referencia más segura.',u:'Si se amplía, el mercado está pidiendo más compensación por riesgo. Conviene leerlo junto al VIX.',f:'ICE BofA, publicado a través de FRED.'},\r\ntreasury10y:{t:'Treasury a 10 años',q:'Es el rendimiento de un bono del gobierno de Estados Unidos a diez años.',u:'Resume expectativas de inflación, crecimiento y condiciones financieras a largo plazo. No es igual a la tasa que decide la Fed.',f:'Departamento del Tesoro de EE. UU., vía FRED.'},\r\ninflation:{t:'Inflación CPI anual',q:'Compara el índice de precios al consumidor del mes actual con el mismo mes del año anterior.',u:'Ayuda a observar la presión general de precios. Una sola lectura no explica las causas de la inflación.',f:'Bureau of Labor Statistics (BLS), vía FRED.'},\r\ndiesel:{t:'Diésel minorista',q:'Es el precio promedio del diésel minorista en Estados Unidos.',u:'Es un coste importante para transporte, logística, agricultura y producción; sus variaciones pueden trasladarse a otros precios.',f:'Energy Information Administration (EIA), vía FRED.'},\r\nrrp:{t:'Acuerdo de recompra inversa nocturno (ON RRP)',q:'Es una herramienta de política monetaria con la que la Reserva Federal gestiona temporalmente la liquidez y ayuda a controlar las tasas de interés de corto plazo.',u:'La Reserva Federal vende valores temporalmente a instituciones elegibles y acuerda recomprarlos al siguiente día hábil. El indicador muestra cuánto efectivo participa y debe leerse junto con las reservas bancarias y la Cuenta General del Tesoro.',f:'Reserva Federal de Nueva York, vía FRED.'},\r\ntga:{t:'Cuenta General del Tesoro (Treasury General Account, TGA)',q:'Es la cuenta operativa principal del Tesoro de Estados Unidos.',u:'Cuando cambia, puede modificar temporalmente dónde está el efectivo dentro del sistema financiero.',f:'Junta de Gobernadores de la Reserva Federal, vía FRED.'},\r\nreserves:{t:'Reservas bancarias',q:'Son saldos que las instituciones depositarias mantienen en la Reserva Federal.',u:'Aportan información sobre la plomería financiera, pero no representan por sí solas toda la liquidez ni todo el crédito.',f:'Board of Governors de la Reserva Federal, vía FRED.'},\r\nclaims:{t:'Solicitudes iniciales de desempleo',q:'Cuenta las nuevas solicitudes semanales de seguro de desempleo, ajustadas por estacionalidad.',u:'Puede detectar con mayor rapidez cambios en el mercado laboral; se complementa con el informe mensual de empleo.',f:'Employment and Training Administration, vía FRED.'}\r\n};\r\nfunction fichasBotones(){document.querySelectorAll('.chart').forEach(c=>{let key=c.querySelector('.plot')?.dataset.k,h=c.querySelector('h3');if(!key||!h||h.parentElement.querySelector('.fact'))return;let b=document.createElement('button');b.type='button';b.className='fact';b.textContent='¿Qué es?';b.onclick=()=>{let x=fichas[key];$('factBody').innerHTML=`<h2>${x.t}</h2><p><b>Qué es:</b> ${x.q}</p><p><b>Cómo leerlo:</b> ${x.u}</p><p><b>Fuente:</b> ${x.f}</p><p>Esta ficha es educativa; no es una recomendación de compra o venta.</p>`;$('factDialog').showModal()};h.after(b)})}\r\nconst institucion=Array.from(document.querySelectorAll('#guide .card')).find(x=>x.querySelector('h2')?.textContent.includes('Instituciones y fuentes'));if(institucion)institucion.innerHTML='<h2>Instituciones y fuentes: quién hace qué</h2><p><b>Sistema de la Reserva Federal (Federal Reserve System, Fed):</b> influye en las condiciones monetarias y supervisa partes del sistema bancario. Su presidente es Kevin Warsh.</p><p><b>Departamento del Tesoro de Estados Unidos (U.S. Department of the Treasury):</b> administra las finanzas del gobierno federal y la <b>Cuenta General del Tesoro (Treasury General Account, TGA)</b>. Su secretario es Scott Bessent.</p><p><b>Oficina de Estadísticas Laborales (Bureau of Labor Statistics, BLS):</b> publica empleo, inflación CPI, salarios y productividad. <b>Oficina de Análisis Económico (Bureau of Economic Analysis, BEA):</b> publica PIB, consumo e ingresos.</p><p><b>Administración de Información Energética de Estados Unidos (U.S. Energy Information Administration, EIA):</b> publica estadísticas energéticas como el diésel. No es la Agencia Internacional de Energía.</p><p><b>Reserva Federal de Chicago (Federal Reserve Bank of Chicago):</b> es un banco regional del sistema Fed. <b>Cboe:</b> mantiene la metodología del VIX y no es un organismo gubernamental.</p><div class=\"callout\"><b>Nota:</b> los cargos pueden cambiar; fueron consultados el 2 de octubre de 2026.</div>';\r\n$('guide').insertAdjacentHTML('beforeend','<article class=\"card\"><h2>Diccionario en español y ejemplos de lectura</h2><h3>Volatilidad y crédito</h3><p><b>Índice de volatilidad (Volatility Index, VIX):</b> resume la volatilidad esperada del mercado de acciones estadounidense. <b>Diferencial ajustado por opciones de bonos de alto rendimiento (Option-Adjusted Spread, High Yield OAS):</b> mide la prima adicional que piden los inversionistas por prestar a empresas con más riesgo.</p><p><b>Ejemplo del circuito económico:</b> si el diésel sube con rapidez, transportar alimentos, materiales y mercancías puede hacerse más costoso. Algunas empresas podrían trasladar parte de ese coste a precios. Si la presión persiste, el mercado puede esperar tasas más altas; eso encarece el crédito y puede afectar consumo e inversión. No es una cadena automática: hay retrasos y otros factores.</p><h3>Liquidez, con nombres completos</h3><p><b>Acuerdos de recompra inversa a un día (Overnight Reverse Repurchase Agreements, RRP):</b> facilidad mediante la cual algunas instituciones colocan efectivo temporalmente en la Reserva Federal.</p><p><b>Cuenta General del Tesoro (Treasury General Account, TGA):</b> cuenta operativa principal del Tesoro de Estados Unidos. <b>Reservas bancarias (Bank Reserves):</b> son saldos que las instituciones depositarias mantienen en la Reserva Federal.</p><p><b>Ejemplo de liquidez:</b> si aumenta el saldo de la Cuenta General del Tesoro porque entra efectivo allí, parte de ese dinero puede dejar temporalmente otras áreas del sistema. Si al mismo tiempo las reservas bancarias bajan, el tablero marca una señal para observar. Eso no confirma una crisis: se compara con RRP, crédito y la evolución de varias semanas.</p></article>');\r\nM.consumer=['Sentimiento del consumidor (Consumer Sentiment)','índice'];C.consumer='#db2777';fichas.consumer={t:'Sentimiento del consumidor de Michigan (Consumer Sentiment)',q:'Es una encuesta mensual sobre cómo los hogares perciben su economía personal y el entorno económico.',u:'No mide inflación ni empleo directamente. Sirve para comparar el ánimo de los hogares con los cambios de precios y el mercado laboral.',f:'Universidad de Michigan, publicado a través de FRED.'};const dibujarOriginal=draw;draw=function(){dibujarOriginal();if(!market.series?.consumer)return;const caja=$('charts');caja.insertAdjacentHTML('beforeend','<article class=\"chart\"><h3>Hogares: precios y confianza</h3><p class=\"note\">Compara esta tarjeta con la inflación anual: precios altos y confianza bajando pueden señalar presión sobre los hogares, pero no prueban una causa única.</p></article>');caja.insertAdjacentHTML('beforeend',chart('consumer'));fichasBotones()};\r\nnew MutationObserver(fichasBotones).observe($('charts'),{childList:true});new MutationObserver(()=>{let a=parseFloat(($('needle').style.transform.match(/-?\\d+(?:\\.\\d+)?/)||[0])[0]);let n=Math.round((a+90)/1.8);if(n>=0&&n<=100)$('score').innerHTML=n+'<small>/100</small>'}).observe($('needle'),{attributes:true,attributeFilter:['style']});$('closeFact').onclick=()=>$('factDialog').close();$('factDialog').onclick=e=>{if(e.target===$('factDialog'))$('factDialog').close()};\r\n</script><script>\r\n/* Aclaración educativa del ON RRP, con vocabulario técnico y propósito económico. */\r\nconst explicacionRrp=Array.from(document.querySelectorAll('#guide p')).find(p=>p.textContent.includes('Acuerdos de recompra inversa a un día'));\r\nif(explicacionRrp)explicacionRrp.outerHTML='<div class=\"callout\"><h3>Acuerdo de recompra inversa nocturno (Overnight Reverse Repurchase Agreement, ON RRP)</h3><p><b>Qué es y para qué sirve:</b> es una herramienta de política monetaria utilizada por la Reserva Federal de Estados Unidos para gestionar temporalmente la liquidez del sistema financiero y ayudar a controlar las tasas de interés de corto plazo.</p><p><b>Cómo funciona:</b> al cierre del Día 1, una institución financiera elegible entrega efectivo a la Reserva Federal. Como garantía, la Reserva Federal vende temporalmente valores, normalmente títulos del Tesoro, y acuerda recomprarlos el siguiente día hábil. En el Día 2 recompra los valores y paga el interés previamente fijado, la tasa ON RRP.</p><p><b>Lectura económica:</b> esta operación puede absorber efectivo durante la noche y ofrecer una alternativa segura a participantes elegibles. La tasa ON RRP contribuye a establecer un piso para ciertas tasas de muy corto plazo; no es una regla absoluta para todos los préstamos privados. El indicador se interpreta junto con las reservas bancarias, la Cuenta General del Tesoro y las condiciones de crédito.</p></div>';\r\n</script><style>\r\n/* Velocímetro: escala uniforme, con marcas exteriores cada diez puntos. */\r\n.gauge.gauge-dial{width:min(300px,100%);height:190px;overflow:visible;margin:4px auto 0;position:relative}.gauge-dial svg{display:block;width:100%;height:180px;overflow:visible}.gauge-dial .gauge-arc{fill:none;stroke:url(#gaugeGradient);stroke-width:24;stroke-linecap:butt}.gauge-dial .gauge-tick{stroke:var(--t);stroke-width:2;stroke-linecap:round}.gauge-dial .gauge-tick.major{stroke-width:3}.gauge-dial .gauge-number{fill:var(--t);font-size:12px;font-weight:800;text-anchor:middle;dominant-baseline:middle}.gauge-dial .gauge-pointer{stroke:var(--t);stroke-width:4;stroke-linecap:round}.gauge-dial .gauge-hub{fill:var(--t);stroke:var(--p);stroke-width:3}.gauge-dial .gauge-value{z-index:3;bottom:28px;font-size:2.15rem;color:var(--t);pointer-events:none}.gauge-dial .gauge-value small{font-size:.86rem}.gauge-caption{margin-top:-1px}\r\n</style><script>\r\n/* Reconstruye el radar como un velocímetro: 0–100, marcas cada 10 y texto fuera del arco. */\r\nconst contenedorDial=document.querySelector('.gauge');\r\nif(contenedorDial){\r\n  const punto=(valor,radio)=>{const ang=(180-valor*1.8)*Math.PI/180;return [150+radio*Math.cos(ang),150-radio*Math.sin(ang)]};\r\n  let marcas='';\r\n  for(let valor=0;valor<=100;valor+=10){\r\n    const mayor=valor%20===0,[x1,y1]=punto(valor,133),[x2,y2]=punto(valor,mayor?117:121),[tx,ty]=punto(valor,148);\r\n    marcas+=`<line class=\"gauge-tick ${mayor?'major':''}\" x1=\"${x1}\" y1=\"${y1}\" x2=\"${x2}\" y2=\"${y2}\"/><text class=\"gauge-number\" x=\"${tx}\" y=\"${ty}\">${valor}</text>`;\r\n  }\r\n  contenedorDial.className='gauge gauge-dial';\r\n  contenedorDial.setAttribute('aria-label','Velocímetro de atención de cero a cien');\r\n  contenedorDial.innerHTML=`<svg viewBox=\"0 0 300 180\" role=\"img\" aria-label=\"Escala de atención de 0 a 100\"><defs><linearGradient id=\"gaugeGradient\" x1=\"0%\" x2=\"100%\"><stop offset=\"0%\" stop-color=\"#16a34a\"/><stop offset=\"48%\" stop-color=\"#eab308\"/><stop offset=\"100%\" stop-color=\"#dc2626\"/></linearGradient></defs><path class=\"gauge-arc\" d=\"M30 150 A120 120 0 0 1 270 150\"/>${marcas}<g id=\"needle\" transform=\"rotate(-90 150 150)\"><line class=\"gauge-pointer\" x1=\"150\" y1=\"150\" x2=\"150\" y2=\"58\"/><circle class=\"gauge-hub\" cx=\"150\" cy=\"150\" r=\"8\"/></g></svg><div id=\"score\" class=\"gauge-value\">—<small>/100</small></div>`;\r\n}\r\nconst calcularVelocimetro=overall;\r\noverall=function(){\r\n  calcularVelocimetro();\r\n  const giro=(($('needle').style.transform||'').match(/-?\\d+(?:\\.\\d+)?/)||[0])[0];\r\n  const valor=Math.max(0,Math.min(100,Math.round((Number(giro)+90)/1.8)));\r\n  $('needle').setAttribute('transform',`rotate(${Number(giro)} 150 150)`);\r\n  $('needle').style.transform='';\r\n  $('score').innerHTML=valor+'<small>/100</small>';\r\n};\r\n</script><script>\r\n/* Completa las doce lecturas educativas del radar. */\r\nM.consumer=['Sentimiento del consumidor (Consumer Sentiment)','índice'];\r\nM.payrolls=['Variación del empleo no agrícola (Nonfarm Payrolls)','miles de empleos netos'];\r\nM.nfci=['Condiciones financieras nacionales (NFCI)','índice'];\r\nC.consumer='#db2777';C.payrolls='#0f766e';C.nfci='#7c3aed';\r\nfichas.payrolls={t:'Variación del empleo no agrícola (Nonfarm Payrolls)',q:'Mide el cambio mensual del empleo asalariado no agrícola en Estados Unidos.',u:'Una cifra débil puede señalar enfriamiento laboral; debe compararse con solicitudes de desempleo, salarios y revisiones de meses anteriores.',f:'Oficina de Estadísticas Laborales de EE. UU. (BLS), vía FRED.'};\r\nfichas.nfci={t:'Índice Nacional de Condiciones Financieras (National Financial Conditions Index, NFCI)',q:'Resume semanalmente condiciones de riesgo, crédito y liquidez de los mercados financieros estadounidenses.',u:'Valores por encima de cero suelen indicar condiciones más restrictivas que el promedio histórico; valores negativos, condiciones más holgadas. Es contexto, no una predicción.',f:'Reserva Federal de Chicago, vía FRED.'};\r\nconst prepararDoce=prep;\r\nprep=function(k,a){\r\n  const p=prepararDoce(k,a);\r\n  if(k==='payrolls')return p.slice(1).map((x,i)=>({date:x.date,value:x.value-p[i].value}));\r\n  return p;\r\n};\r\nconst formatoDoce=f;\r\nf=function(v,k){return k==='payrolls'&&Number.isFinite(v)?Math.round(v).toLocaleString('es-VE'):formatoDoce(v,k)};\r\nconst estadoDoce=state;\r\nstate=function(k,a){\r\n  const z=estadoDoce(k,a),p=prep(k,a),v=p.at(-1)?.value||0;\r\n  if(k==='consumer'){z.s=v<55?70:v<70?42:18;z.r=v<55?'Confianza de hogares débil':v<70?'Confianza de hogares por vigilar':'Confianza de hogares relativamente firme'}\r\n  if(k==='payrolls'){z.s=v<50?76:v<120?46:18;z.r=v<50?'Creación de empleo débil':v<120?'Empleo creciendo con cautela':'Creación de empleo firme'}\r\n  if(k==='nfci'){z.s=v>=.5?76:v>=0?48:18;z.r=v>=.5?'Condiciones financieras restrictivas':v>=0?'Condiciones financieras por vigilar':'Condiciones financieras holgadas'}\r\n  z.t=z.s>=60?'red':z.s>=30?'yellow':'green';z.label=z.t==='red'?'Atención elevada':z.t==='yellow'?'Atención':'Tranquilo';return z;\r\n};\r\nrows=function(){\r\n  const a=[\r\n    ['Índice de volatilidad (VIX)','vix','Volatilidad esperada implícita en opciones sobre el S&P 500.'],\r\n    ['Diferencial de alto rendimiento (High Yield OAS)','credit','Prima adicional por prestar a empresas con más riesgo.'],\r\n    ['Bono del Tesoro a 10 años','treasury10y','Contexto de las tasas de largo plazo.'],\r\n    ['Inflación anual de precios (CPI)','inflation','Cambio de precios frente al mismo mes del año previo.'],\r\n    ['Diésel minorista','diesel','Coste relevante para transporte, logística y producción.'],\r\n    ['Acuerdo de recompra inversa nocturno (ON RRP)','rrp','Herramienta de liquidez de muy corto plazo de la Reserva Federal.'],\r\n    ['Cuenta General del Tesoro (TGA)','tga','Cuenta operativa principal del Tesoro de EE. UU.'],\r\n    ['Reservas bancarias','reserves','Saldos de instituciones depositarias en la Reserva Federal.'],\r\n    ['Solicitudes iniciales de desempleo','claims','Señal semanal temprana sobre el mercado laboral.'],\r\n    ['Sentimiento del consumidor','consumer','Cómo perciben los hogares su situación y el entorno económico.'],\r\n    ['Empleo no agrícola (Nonfarm Payrolls)','payrolls','Cambio mensual del empleo asalariado no agrícola.'],\r\n    ['Condiciones financieras nacionales (NFCI)','nfci','Resumen semanal de riesgo, crédito y liquidez.']\r\n  ];\r\n  $('rows').innerHTML=a.map(x=>{const z=state(x[1],market.series?.[x[1]]?.points||[]);return `<tr><td><span class=\"dot ${z.t==='green'?'':z.t}\"></span><b>${x[0]}</b></td><td>${z.r}</td><td>${x[2]}</td></tr>`}).join('');\r\n};\r\noverall=function(){\r\n  const S=k=>state(k,market.series?.[k]?.points||[]).s;\r\n  const liquidez=(S('rrp')+S('tga')+S('reserves'))/3;\r\n  const n=Math.round(S('credit')*.18+S('vix')*.14+liquidez*.15+S('treasury10y')*.10+S('diesel')*.06+S('inflation')*.09+S('claims')*.08+S('consumer')*.06+S('payrolls')*.08+S('nfci')*.06);\r\n  const claves=['vix','credit','treasury10y','diesel','rrp','tga','reserves','inflation','claims','consumer','payrolls','nfci'];\r\n  const a=claves.map(k=>[k,state(k,market.series?.[k]?.points||[])]),c={green:0,yellow:0,red:0};a.forEach(x=>c[x[1].t]++);\r\n  const titulo=n>=60?'Tensión elevada':n>=30?'Atención':'Entorno tranquilo';\r\n  const principales=a.sort((x,y)=>y[1].s-x[1].s).slice(0,2).map(x=>M[x[0]][0]).join(' y ');\r\n  $('needle').setAttribute('transform',`rotate(${-90+n*1.8} 150 150)`);\r\n  $('score').innerHTML=n+'<small>/100</small>';$('level').textContent=titulo;$('rtitle').textContent=titulo;\r\n  $('rtext').textContent=`Las lecturas que más requieren contexto ahora son ${principales}. El resultado orienta la revisión; no predice mercados.`;\r\n  $('break').innerHTML=`<span class=\"traffic green\">${c.green} tranquilo${c.green===1?'':'s'}</span><span class=\"traffic yellow\">${c.yellow} en atención</span><span class=\"traffic red\">${c.red} con atención elevada</span>`;\r\n};\r\nconst dibujarDoce=draw;\r\ndraw=function(){\r\n  dibujarDoce();\r\n  const explicacionHogares=Array.from($('charts').querySelectorAll('.chart')).find(c=>c.querySelector('h3')?.textContent==='Hogares: precios y confianza');\r\n  if(explicacionHogares)explicacionHogares.remove();\r\n  if(!market.series?.payrolls||!market.series?.nfci)return;\r\n  $('charts').insertAdjacentHTML('beforeend',chart('payrolls')+chart('nfci'));\r\n  const consumidor=Array.from($('charts').querySelectorAll('.chart')).find(c=>c.querySelector('h3')?.textContent.includes('Sentimiento del consumidor'));\r\n  if(consumidor&&!consumidor.querySelector('.household-note'))consumidor.insertAdjacentHTML('beforeend','<p class=\"note household-note\">Compárala con la inflación: precios altos y confianza bajando pueden señalar presión sobre los hogares; no prueban una causa única.</p>');\r\n  fichasBotones();hover();\r\n};\r\n</script><style>\r\n.indicator-pages{display:flex;gap:8px;flex-wrap:wrap;margin:2px 0 15px}.indicator-pages .tab{font-weight:750}.indicator-pages .tab[aria-selected=true]{background:var(--teal);border-color:var(--teal);color:#fff}.indicator-page-note{margin:-5px 0 14px;font-size:.86rem;color:var(--m)}\r\n</style><script>\r\n/* Dos vistas de seis indicadores para leer el tablero sin sobrecarga. */\r\nconst gruposIndicadores={\r\n  principal:['vix','credit','treasury10y','inflation','diesel','nfci'],\r\n  liquidez:['rrp','tga','reserves','claims','consumer','payrolls']\r\n};\r\nlet paginaIndicadores='principal';\r\nconst zonaGraficos=$('charts');\r\nzonaGraficos.insertAdjacentHTML('beforebegin','<div class=\"indicator-pages\" role=\"tablist\" aria-label=\"Grupos de indicadores\"><button class=\"tab indicator-page\" type=\"button\" data-page=\"principal\" aria-selected=\"true\">Panorama principal · 6</button><button class=\"tab indicator-page\" type=\"button\" data-page=\"liquidez\" aria-selected=\"false\">Liquidez y economía · 6</button></div><p id=\"indicatorPageNote\" class=\"indicator-page-note\">Riesgo, crédito, tasas, precios, energía y condiciones financieras.</p>');\r\nconst notasIndicadores={principal:'Riesgo, crédito, tasas, precios, energía y condiciones financieras.',liquidez:'Movimiento de efectivo, actividad laboral y percepción de los hogares.'};\r\nfunction filtrarIndicadores(){\r\n  const activos=gruposIndicadores[paginaIndicadores];\r\n  Array.from(zonaGraficos.querySelectorAll('.chart')).forEach(c=>{const clave=c.querySelector('.plot')?.dataset.k;c.hidden=!!clave&&!activos.includes(clave)});\r\n  Array.from($('rows').querySelectorAll('tr')).forEach((fila,i)=>{const claves=['vix','credit','treasury10y','inflation','diesel','rrp','tga','reserves','claims','consumer','payrolls','nfci'];fila.hidden=!activos.includes(claves[i])});\r\n  $('indicatorPageNote').textContent=notasIndicadores[paginaIndicadores];\r\n}\r\ndocument.querySelectorAll('.indicator-page').forEach(b=>b.onclick=()=>{paginaIndicadores=b.dataset.page;document.querySelectorAll('.indicator-page').forEach(x=>x.setAttribute('aria-selected',x===b));filtrarIndicadores()});\r\nconst dibujarConPestanas=draw;\r\ndraw=function(){dibujarConPestanas();filtrarIndicadores()};\r\n</script><style>\r\n.radar-block{min-width:0;background:var(--p2);border:1px solid var(--l);border-radius:15px;padding:18px}.radar-score{text-align:center}.radar-score .break{justify-content:center}.radar-reading{text-align:left;margin-top:4px}.radar-reading h2{font-size:1.08rem}.radar-reading p{margin-top:7px!important}.radar-context h2{font-size:1.06rem;margin-bottom:8px}.radar-context p{font-size:.92rem}.radar-context p+p{margin-top:10px}@media(max-width:900px){.radar-block{padding:15px}}\r\n</style><script>\r\n/* Reorganiza la parte superior y da todo el ancho a las señales de cada pestaña. */\r\nconst panelRadar=document.querySelector('.radar');\r\nconst bloqueMedidor=panelRadar?.firstElementChild;\r\nconst bloqueLectura=panelRadar?.lastElementChild;\r\nconst tarjetaSenales=$('rows')?.closest('.card');\r\nconst tarjetaAyuda=tarjetaSenales?.nextElementSibling;\r\nif(panelRadar&&bloqueMedidor&&bloqueLectura&&tarjetaAyuda){\r\n  bloqueMedidor.classList.add('radar-block','radar-score');\r\n  bloqueLectura.className='radar-reading';\r\n  bloqueMedidor.append(bloqueLectura);\r\n  const contexto=document.createElement('section');\r\n  contexto.className='radar-block radar-context';\r\n  contexto.innerHTML=tarjetaAyuda.innerHTML;\r\n  panelRadar.append(contexto);\r\n  tarjetaAyuda.remove();\r\n}\r\nif(tarjetaSenales){tarjetaSenales.classList.remove('s7');tarjetaSenales.classList.add('s12');}\r\nconst tituloSenales=tarjetaSenales?.querySelector('h2');\r\nconst textoSenales=tarjetaSenales?.querySelector('.head p');\r\nconst filtrarSenalesOriginal=filtrarIndicadores;\r\nfiltrarIndicadores=function(){\r\n  filtrarSenalesOriginal();\r\n  const nombre=paginaIndicadores==='principal'?'Panorama principal':'Liquidez y economía';\r\n  if(tituloSenales)tituloSenales.textContent='Señales a vigilar · '+nombre;\r\n  if(textoSenales)textoSenales.textContent='Las seis señales correspondientes a los gráficos que estás consultando arriba.';\r\n};\r\n</script><style>\r\n.radar{grid-template-columns:repeat(3,minmax(0,1fr));align-items:stretch}.radar-block{display:flex;flex-direction:column}.radar-score .gauge{margin:auto}.radar-score .radar-reading{margin-top:4px}.radar-summary{justify-content:center}.radar-summary .break{margin-top:auto}@media(max-width:900px){.radar{grid-template-columns:1fr}}\r\n</style><script>\r\n/* Divide la cabecera en velocímetro, lectura central y orientación. */\r\nconst radarTres=document.querySelector('.radar');\r\nconst lecturaCentral=document.querySelector('.radar-reading');\r\nif(radarTres&&lecturaCentral&&!radarTres.querySelector('.radar-summary')){\r\n  const resumen=document.createElement('section');\r\n  resumen.className='radar-block radar-summary';\r\n  resumen.append(lecturaCentral);\r\n  radarTres.insertBefore(resumen,radarTres.children[1]);\r\n}\r\n</script><script>\r\n/* Orden final de la cabecera: atención, velocímetro, orientación. */\r\nconst cabeceraRadar=document.querySelector('.radar');\r\nconst atencionRadar=cabeceraRadar?.querySelector('.radar-summary');\r\nconst velocimetroRadar=cabeceraRadar?.querySelector('.radar-score');\r\nconst ayudaRadar=cabeceraRadar?.querySelector('.radar-context');\r\nif(cabeceraRadar&&atencionRadar&&velocimetroRadar&&ayudaRadar)cabeceraRadar.append(atencionRadar,velocimetroRadar,ayudaRadar);\r\n</script><style>\r\n.guide-nav{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 16px}.guide-nav .tab[aria-selected=true]{background:var(--teal);border-color:var(--teal);color:#fff}.guide-page[hidden]{display:none}.circuit-flow{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:18px 0}.circuit-flow span{border:1px solid var(--l);border-radius:12px;padding:12px;font-weight:750;text-align:center;color:var(--t);font-size:.88rem}.circuit-flow span:nth-child(1){background:#fef3c7}.circuit-flow span:nth-child(2){background:#ffedd5}.circuit-flow span:nth-child(3){background:#dbeafe}.circuit-flow span:nth-child(4){background:#ede9fe}.example{margin-top:10px;border-left:4px solid var(--teal);background:var(--p2);border-radius:8px;padding:12px 14px;color:var(--t)}.guide-pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.guide-pair .card{margin:0}@media(max-width:760px){.circuit-flow,.guide-pair{grid-template-columns:1fr}}\r\n</style><script>\r\n/* Guía educativa separada en lectura, fuentes e instituciones. */\r\nconst guia=$('guide');\r\nguia.innerHTML=`\r\n  <nav class=\"guide-nav\" aria-label=\"Secciones de la guía\">\r\n    <button class=\"tab guide-tab\" type=\"button\" data-guide-page=\"leer\" aria-selected=\"true\">Cómo leer el radar</button>\r\n    <button class=\"tab guide-tab\" type=\"button\" data-guide-page=\"fuentes\">Fuentes y frecuencia</button>\r\n    <button class=\"tab guide-tab\" type=\"button\" data-guide-page=\"instituciones\">Instituciones: quién hace qué</button>\r\n  </nav>\r\n  <section class=\"guide-page\" data-page=\"leer\">\r\n    <article class=\"card\"><p class=\"ey\">Guía del tablero</p><h2>Cómo leer el radar de mercados</h2><p>Este tablero reúne datos públicos para ordenar preguntas, no para adivinar el futuro. Observa dirección, velocidad y coincidencias entre indicadores; una cifra aislada no confirma una conclusión.</p></article>\r\n    <article class=\"card\"><h2>1. La economía como un circuito</h2><p>Una manera sencilla de pensar el tablero es seguir esta cadena.</p><div class=\"circuit-flow\"><span>Costes de energía y transporte</span><span>Precios e inflación</span><span>Tasas y coste del crédito</span><span>Consumo, inversión y riesgo</span></div><p>No es una ley automática: es una guía para ordenar lo que puede estar ocurriendo. Los efectos pueden tener retrasos, intensidad distinta y causas adicionales.</p><h3>Inflación anual de precios (Consumer Price Index, CPI)</h3><p>Mide cómo cambia el nivel de precios respecto al mismo mes del año anterior. Una inflación persistente puede contribuir a condiciones financieras más restrictivas.</p><div class=\"example\"><b>Ejemplo:</b> si el diésel aumenta con rapidez, puede elevar costes de transporte y logística. Algunas empresas podrían trasladar parte de ese coste a precios. No toda subida de diésel se convierte automáticamente en inflación general.</div><h3>Rendimiento del bono del Tesoro de Estados Unidos a 10 años (U.S. Treasury 10-Year Yield)</h3><p>Refleja expectativas de inflación, crecimiento y compensación por prestar a largo plazo. No es la tasa que fija directamente la Reserva Federal, pero influye en hipotecas, financiación empresarial y valoración de activos.</p><div class=\"example\"><b>Ejemplo:</b> si el rendimiento a 10 años aumenta y permanece alto, financiar una vivienda o una empresa puede resultar más costoso; el efecto depende también de las tasas bancarias y del resto de la economía.</div></article>\r\n    <article class=\"card\"><h2>2. Riesgo, protección y crédito</h2><h3>Índice de volatilidad (Volatility Index, VIX)</h3><p>Resume la volatilidad esperada a corto plazo que está implícita en opciones sobre el S&amp;P 500. Cuando la protección mediante opciones se encarece, el VIX suele subir.</p><h3>Diferencial ajustado por opciones de bonos de alto rendimiento (Option-Adjusted Spread, High Yield OAS)</h3><p>Mide la prima adicional que los inversionistas exigen para prestar a empresas con más riesgo frente a una referencia de menor riesgo.</p><div class=\"example\"><b>Ejemplo:</b> un VIX alto durante un día puede responder a una noticia. Si el VIX y el diferencial de crédito suben y se mantienen elevados durante semanas, la cautela del mercado es más amplia; aun así, no confirma un desenlace.</div></article>\r\n    <article class=\"card\"><h2>3. Liquidez</h2><h3>Acuerdo de recompra inversa nocturno (Overnight Reverse Repurchase Agreement, ON RRP)</h3><p>Herramienta de política monetaria con la que la Reserva Federal gestiona temporalmente liquidez y ayuda a controlar tasas de corto plazo. La explicación completa está en el botón <b>¿Qué es?</b> de su tarjeta.</p><h3>Cuenta General del Tesoro (Treasury General Account, TGA)</h3><p>Es la cuenta operativa principal del Tesoro de Estados Unidos.</p><h3>Reservas bancarias (Bank Reserves)</h3><p>Son saldos que las instituciones depositarias mantienen en la Reserva Federal. Las tres lecturas se muestran en miles de millones de USD para facilitar su lectura.</p><div class=\"example\"><b>Ejemplo:</b> si sube el saldo de la Cuenta General del Tesoro y, al mismo tiempo, bajan reservas bancarias, conviene mirar la evolución de RRP y crédito. Es una señal para observar, no una confirmación de crisis.</div></article>\r\n    <article class=\"card\"><h2>4. Semáforos y radar de atención</h2><p>Cada tarjeta recibe una luz verde, amarilla o roja con una explicación corta. Son umbrales educativos y modificables; no son un sistema de inversión ni una alerta automática de crisis.</p><p>El radar agrega las doce señales para ayudar a decidir qué revisar primero. De 0 a 29 indica entorno tranquilo; de 30 a 59, atención; de 60 a 100, tensión elevada.</p></article>\r\n    <article class=\"card\"><h2>Rutina práctica</h2><ol><li>Mira el marcador general y las lecturas que más requieren contexto.</li><li>Revisa las tarjetas amarillas o rojas y el periodo elegido.</li><li>Pasa el ratón sobre un gráfico para comprobar la fecha y el valor exacto.</li><li>Busca coincidencias entre crédito, volatilidad, liquidez, inflación y empleo.</li></ol></article>\r\n  </section>\r\n  <section class=\"guide-page\" data-page=\"fuentes\" hidden>\r\n    <article class=\"card\"><h2>Fuentes y frecuencia</h2><p>El tablero usa series públicas distribuidas por FRED y por organismos oficiales. Una serie diaria, semanal o mensual conserva su frecuencia original: los botones de periodo cambian la ventana de lectura, no convierten una serie mensual en diaria.</p><ul><li><a href=\"https://fred.stlouisfed.org/series/VIXCLS\" target=\"_blank\" rel=\"noopener\">Índice de volatilidad (VIX) en FRED</a> · diario.</li><li><a href=\"https://fred.stlouisfed.org/series/CPIAUCSL\" target=\"_blank\" rel=\"noopener\">Índice de precios al consumidor (CPI) en FRED</a> · mensual.</li><li><a href=\"https://home.treasury.gov/policy-issues/financing-the-government/interest-rate-statistics\" target=\"_blank\" rel=\"noopener\">Rendimientos del Tesoro de Estados Unidos</a> · diario.</li><li><a href=\"https://www.chicagofed.org/research/data/nfci/current-data\" target=\"_blank\" rel=\"noopener\">Índice Nacional de Condiciones Financieras (NFCI)</a> · semanal.</li></ul><div class=\"callout\"><b>Importante:</b> las publicaciones pueden tener retrasos y revisiones. El tablero muestra la última observación pública disponible.</div></article>\r\n  </section>\r\n  <section class=\"guide-page\" data-page=\"instituciones\" hidden>\r\n    <article class=\"card\"><h2>Instituciones y fuentes: quién hace qué</h2><p><b>Sistema de la Reserva Federal (Federal Reserve System, Fed):</b> influye en las condiciones monetarias y supervisa partes del sistema bancario. El presidente de la Junta de Gobernadores es Kevin Warsh.</p><p><b>Departamento del Tesoro de Estados Unidos (U.S. Department of the Treasury):</b> administra las finanzas federales y la Cuenta General del Tesoro. El secretario es Scott Bessent.</p><p><b>Oficina de Estadísticas Laborales (Bureau of Labor Statistics, BLS):</b> publica empleo, inflación CPI, salarios y productividad. Su comisionado es Brett Matsumoto.</p><p><b>Oficina de Análisis Económico (Bureau of Economic Analysis, BEA):</b> publica PIB, consumo e ingresos. Su director es Vipin Arora.</p><p><b>Administración de Información Energética de Estados Unidos (U.S. Energy Information Administration, EIA):</b> publica estadísticas de energía, incluido el diésel. <b>Reserva Federal de Chicago (Federal Reserve Bank of Chicago):</b> publica el NFCI.</p><p><b>Cboe:</b> mantiene la metodología del VIX; no es una institución gubernamental.</p><div class=\"callout\"><b>Nota:</b> los cargos pueden cambiar. Esta ficha se consultó el 2 de octubre de 2026.</div></article>\r\n  </section>`;\r\ndocument.querySelectorAll('.guide-tab').forEach(b=>b.onclick=()=>{const destino=b.dataset.guidePage;document.querySelectorAll('.guide-tab').forEach(x=>x.setAttribute('aria-selected',x===b));document.querySelectorAll('.guide-page').forEach(x=>x.hidden=x.dataset.page!==destino);scrollTo({top:0,behavior:'smooth'})});\r\n</script><style>\r\n.top{align-items:center;text-align:center}.top>div:first-child{max-width:820px}.top h1{text-transform:uppercase}.top .actions{justify-content:center}.tabs,.guide-nav{justify-content:center}.tab{text-transform:uppercase;letter-spacing:.045em;font-size:.76rem}.reading-note{max-width:1000px;margin:0 auto}.reading-note .card{margin-bottom:16px}.reading-note h2{font-size:1.35rem;margin-bottom:10px}.reading-note p,.reading-note li{color:var(--t);font-size:1.02rem;line-height:1.7}\r\n</style><script>\r\n/* Cabecera centrada y pestaña educativa independiente sobre los límites del radar. */\r\nconst navegacionPrincipal=document.querySelector('nav.tabs');\r\nconst lecturaNoPrediccion=document.createElement('section');\r\nlecturaNoPrediccion.id='lectura';lecturaNoPrediccion.className='reading-note';lecturaNoPrediccion.hidden=true;\r\nlecturaNoPrediccion.innerHTML='<article class=\"card\"><p class=\"ey\">Uso responsable</p><h2>Lectura, no predicción</h2><p>Una señal aislada no confirma una crisis, una recesión ni una oportunidad de inversión. El tablero reúne información pública para observar cambios y preguntas relevantes, no para anticipar con certeza lo que ocurrirá.</p><div class=\"callout\"><b>Qué mirar:</b> la dirección de cada gráfico, la rapidez del movimiento, la duración y si otras señales cuentan una historia parecida.</div></article><article class=\"card\"><h2>Cómo interpretar una alerta</h2><ul><li>Una luz amarilla significa que conviene mirar el indicador con más atención.</li><li>Una luz roja significa que la regla educativa detectó un valor o cambio que requiere contexto.</li><li>Antes de extraer conclusiones, compara distintas frecuencias, revisa fuentes y considera que los datos pueden corregirse.</li></ul><p>Este tablero no sustituye información profesional, análisis propio ni decisiones adaptadas a la situación personal de cada persona.</p></article>';\r\nguia.insertAdjacentElement('afterend',lecturaNoPrediccion);\r\nnavegacionPrincipal.innerHTML='<button class=\"tab main-view\" type=\"button\" data-main-view=\"dash\" aria-selected=\"true\">TABLERO</button><button class=\"tab main-view\" type=\"button\" data-main-view=\"leer\" aria-selected=\"false\">CÓMO LEER EL RADAR</button><button class=\"tab main-view\" type=\"button\" data-main-view=\"lectura\" aria-selected=\"false\">LECTURA, NO PREDICCIÓN</button>';\r\ndocument.querySelectorAll('.main-view').forEach(b=>b.onclick=()=>{const vista=b.dataset.mainView;$('dash').hidden=vista!=='dash';guia.hidden=vista!=='leer';lecturaNoPrediccion.hidden=vista!=='lectura';document.querySelectorAll('.main-view').forEach(x=>x.setAttribute('aria-selected',x===b));scrollTo({top:0,behavior:'smooth'})});\r\n</script><style>\r\n.radar-summary #rtitle{margin-bottom:8px}.radar-summary #rtext{text-align:justify;line-height:1.65;margin-top:0!important}.radar-summary .break{gap:7px;margin-top:16px}.dashboard .head h2{text-transform:uppercase;letter-spacing:.045em}\r\n</style><script>\r\n/* Presentación más limpia de la lectura central y de los semáforos. */\r\nconst actualizarLecturaCentral=overall;\r\noverall=function(){\r\n  actualizarLecturaCentral();\r\n  const texto=$('rtext');\r\n  texto.textContent=texto.textContent.replace('Las lecturas que más requieren contexto ahora son ','Lecturas prioritarias para revisar ahora: ').replace(' El resultado orienta la revisión; no predice mercados.','');\r\n  $('break').querySelectorAll('.traffic').forEach(x=>{x.textContent=x.textContent.replace(' tranquilo',' Tranquilo').replace(' en atención',' En atención').replace(' con atención elevada',' Con atención elevada')});\r\n};\r\n</script><script>\r\n/* Precisión educativa: nombres completos y consistentes en el ejemplo de liquidez. */\r\nconst ejemploLiquidez = Array.from(document.querySelectorAll('#guide .example')).find((elemento) =>\r\n  elemento.textContent.includes('si sube el saldo de la Cuenta General del Tesoro')\r\n);\r\nif (ejemploLiquidez) {\r\n  ejemploLiquidez.innerHTML = '<b>Ejemplo:</b> si sube el saldo de la <b>Cuenta General del Tesoro</b> y, al mismo tiempo, bajan las <b>Reservas Bancarias</b>, conviene observar la evolución del <b>Acuerdo de Recompra Inversa Nocturno (ON RRP)</b> y del <b>Crédito</b>. Es una señal para observar, no una confirmación de crisis.';\r\n}\r\n</script><script>\r\n/* Lectura escalonada y clara del Semáforo de Radar de Atención. */\r\nconst semaforoRadar = Array.from(document.querySelectorAll('#guide article.card')).find((articulo) =>\r\n  articulo.querySelector('h2')?.textContent.includes('Semáforos y radar de atención')\r\n);\r\nif (semaforoRadar) {\r\n  semaforoRadar.innerHTML = '<h2>4. Semáforo de Radar de Atención</h2><p>Cada tarjeta recibe una luz verde, amarilla o roja con una explicación corta. Son umbrales educativos y modificables; no son un sistema de inversión ni una alerta automática de crisis.</p><p>El Radar agrega las 12 señales para ayudar a decidir qué revisar primero.</p><p>De 0 a 29 indica Entorno Tranquilo.</p><p>De 30 a 59 indica Entorno de Atención.</p><p>De 60 a 100 indica Tensión Elevada.</p>';\r\n}\r\n</script><style>\r\n  .institution{margin:0;padding:0}.institution+.institution{border-top:1px solid var(--line);margin-top:18px;padding-top:18px}\r\n  .source-list{columns:2;column-gap:30px}.source-list li{break-inside:avoid;margin:0 0 12px}@media(max-width:760px){.source-list{columns:1}}\r\n</style><script>\r\n/* Fuentes completas, instituciones separadas y lectura responsable más clara. */\r\nconst guiaFuentes = Array.from(document.querySelectorAll('#guide article.card')).find((articulo) => articulo.querySelector('h2')?.textContent === 'Fuentes y frecuencia');\r\nif (guiaFuentes) {\r\n  guiaFuentes.innerHTML = `<h2>Fuentes y frecuencia</h2>\r\n    <p>Cada indicador conserva la frecuencia con que se publica. Los botones del tablero cambian el período de lectura; no convierten un dato mensual en diario.</p>\r\n    <ul class=\"source-list\">\r\n      <li><a href=\"https://fred.stlouisfed.org/series/VIXCLS\" target=\"_blank\" rel=\"noopener\">Índice de Volatilidad (VIX)</a> · diario · Cboe, distribuido por FRED.</li>\r\n      <li><a href=\"https://fred.stlouisfed.org/series/BAMLH0A0HYM2\" target=\"_blank\" rel=\"noopener\">Diferencial de Bonos de Alto Rendimiento (High Yield OAS)</a> · diario · ICE BofA, distribuido por FRED.</li>\r\n      <li><a href=\"https://fred.stlouisfed.org/series/DGS10\" target=\"_blank\" rel=\"noopener\">Rendimiento del Tesoro a 10 Años</a> · diario · Departamento del Tesoro, distribuido por FRED.</li>\r\n      <li><a href=\"https://fred.stlouisfed.org/series/CPIAUCSL\" target=\"_blank\" rel=\"noopener\">Índice de Precios al Consumidor (CPI)</a> · mensual · BLS, distribuido por FRED.</li>\r\n      <li><a href=\"https://fred.stlouisfed.org/series/GASDESW\" target=\"_blank\" rel=\"noopener\">Diésel Minorista de EE. UU.</a> · semanal · EIA, distribuido por FRED.</li>\r\n      <li><a href=\"https://fred.stlouisfed.org/series/RRPONTSYD\" target=\"_blank\" rel=\"noopener\">Acuerdo de Recompra Inversa Nocturno (ON RRP)</a> · diario · Reserva Federal de Nueva York, distribuido por FRED.</li>\r\n      <li><a href=\"https://fred.stlouisfed.org/series/WTREGEN\" target=\"_blank\" rel=\"noopener\">Cuenta General del Tesoro (TGA)</a> · semanal · Departamento del Tesoro, distribuido por FRED.</li>\r\n      <li><a href=\"https://fred.stlouisfed.org/series/WRESBAL\" target=\"_blank\" rel=\"noopener\">Reservas Bancarias</a> · semanal · Reserva Federal, distribuido por FRED.</li>\r\n      <li><a href=\"https://fred.stlouisfed.org/series/ICSA\" target=\"_blank\" rel=\"noopener\">Solicitudes Iniciales de Desempleo</a> · semanal · Departamento de Trabajo, distribuido por FRED.</li>\r\n      <li><a href=\"https://fred.stlouisfed.org/series/UMCSENT\" target=\"_blank\" rel=\"noopener\">Sentimiento del Consumidor</a> · mensual · Universidad de Míchigan, distribuido por FRED.</li>\r\n      <li><a href=\"https://fred.stlouisfed.org/series/PAYEMS\" target=\"_blank\" rel=\"noopener\">Variación del Empleo no Agrícola (Nonfarm Payrolls)</a> · mensual · BLS, distribuido por FRED.</li>\r\n      <li><a href=\"https://www.chicagofed.org/research/data/nfci/current-data\" target=\"_blank\" rel=\"noopener\">Índice Nacional de Condiciones Financieras (NFCI)</a> · semanal · Reserva Federal de Chicago.</li>\r\n    </ul>\r\n    <div class=\"callout\"><b>Índice de Miedo y Codicia:</b> es una fuente externa de CNN que se desea incorporar, pero todavía no forma parte de los indicadores numéricos: su proveedor no ofrece una descarga automatizada estable para este tablero. El VIX continúa siendo la lectura de volatilidad disponible.</div>\r\n    <div class=\"callout\"><b>Importante:</b> las publicaciones pueden tener retrasos y revisiones. El tablero muestra la última observación pública disponible.</div>`;\r\n}\r\nconst guiaInstituciones = Array.from(document.querySelectorAll('#guide article.card')).find((articulo) => articulo.querySelector('h2')?.textContent.includes('Instituciones y fuentes'));\r\nif (guiaInstituciones) {\r\n  guiaInstituciones.innerHTML = `<h2>Instituciones y fuentes: quién hace qué</h2>\r\n    <section class=\"institution\"><p><b>Sistema de la Reserva Federal (Federal Reserve System, Fed)</b></p><p>Gestiona la política monetaria y supervisa partes del sistema bancario. Publica, entre otras series, las Reservas Bancarias.</p></section>\r\n    <section class=\"institution\"><p><b>Departamento del Tesoro de Estados Unidos (U.S. Department of the Treasury)</b></p><p>Administra las finanzas federales, emite deuda pública y mantiene la Cuenta General del Tesoro.</p></section>\r\n    <section class=\"institution\"><p><b>Oficina de Estadísticas Laborales (Bureau of Labor Statistics, BLS)</b></p><p>Publica inflación, empleo no agrícola, salarios y otras estadísticas laborales.</p></section>\r\n    <section class=\"institution\"><p><b>Oficina de Análisis Económico (Bureau of Economic Analysis, BEA)</b></p><p>Publica PIB, consumo, ingresos y cuentas nacionales. Es fuente educativa relevante, aunque no alimenta una tarjeta actual.</p></section>\r\n    <section class=\"institution\"><p><b>Administración de Información Energética de Estados Unidos (U.S. Energy Information Administration, EIA)</b></p><p>Publica estadísticas energéticas, incluido el diésel minorista.</p></section>\r\n    <section class=\"institution\"><p><b>Reserva Federal de Chicago (Federal Reserve Bank of Chicago)</b></p><p>Publica el Índice Nacional de Condiciones Financieras.</p></section>\r\n    <section class=\"institution\"><p><b>Universidad de Míchigan (University of Michigan)</b></p><p>Elabora el índice de Sentimiento del Consumidor.</p></section>\r\n    <section class=\"institution\"><p><b>Cboe</b></p><p>Mantiene la metodología del Índice de Volatilidad VIX. No es una institución gubernamental.</p></section>\r\n    <section class=\"institution\"><p><b>FRED (Federal Reserve Economic Data)</b></p><p>Es el portal de la Reserva Federal de San Luis que distribuye muchas de las series públicas utilizadas; no produce todas esas estadísticas.</p></section>\r\n    <div class=\"callout\"><b>Nota:</b> los responsables institucionales pueden cambiar. Esta ficha explica las funciones de cada organismo y no depende de un nombre personal.</div>`;\r\n}\r\nif (typeof lecturaNoPrediccion !== 'undefined') {\r\n  const lecturaPrincipal = lecturaNoPrediccion.querySelector('article.card');\r\n  if (lecturaPrincipal) lecturaPrincipal.innerHTML = '<p class=\"ey\">Uso responsable</p><h2>Lectura, no predicción</h2><p>Una señal aislada no confirma una crisis, una recesión ni una oportunidad de inversión.</p><p>El tablero reúne información pública para observar cambios y preguntas relevantes, no para anticipar con certeza lo que ocurrirá.</p><div class=\"callout\"><b>Qué mirar:</b> la dirección de cada gráfico, la rapidez del movimiento, la duración y si otras señales cuentan una historia parecida.</div>';\r\n}\r\n</script><style>\r\n  /* La cabecera usa tres columnas: el título ocupa exactamente el centro visual. */\r\n  .top{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;text-align:center}\r\n  .top>div:first-child{grid-column:2;max-width:820px}\r\n  .top .actions{grid-column:3;justify-self:end;justify-content:flex-end}\r\n  @media(max-width:760px){.top{grid-template-columns:1fr}.top>div:first-child,.top .actions{grid-column:1;justify-self:center}.top .actions{margin-top:14px;flex-wrap:wrap;justify-content:center}}\r\n</style><style>\r\n  .urgent-review{margin-top:14px;padding:12px 13px;border:1px solid var(--l);border-left:4px solid var(--teal);border-radius:10px;background:var(--p);color:var(--t);font-size:.91rem;line-height:1.5}\r\n  .urgent-review.urgent{border-color:#b91c1c;border-left-color:#b91c1c;background:#fef2f2;color:#7f1d1d}\r\n  html[data-theme=dark] .urgent-review.urgent{background:#3b1017;color:#fecaca}\r\n</style><script>\r\n/* Alerta prudente: exige puntuación alta y coincidencia entre varias áreas. */\r\nconst recalcularRadarUrgente = overall;\r\noverall = function () {\r\n  recalcularRadarUrgente();\r\n  const puntaje = (clave) => state(clave, market.series?.[clave]?.points || []).s;\r\n  const liquidez = (puntaje('rrp') + puntaje('tga') + puntaje('reserves')) / 3;\r\n  const radar = Math.round(\r\n    puntaje('credit') * .18 + puntaje('vix') * .14 + liquidez * .15 +\r\n    puntaje('treasury10y') * .10 + puntaje('diesel') * .06 + puntaje('inflation') * .09 +\r\n    puntaje('claims') * .08 + puntaje('consumer') * .06 + puntaje('payrolls') * .08 + puntaje('nfci') * .06\r\n  );\r\n  const areas = [\r\n    ['Riesgo y Crédito', Math.max(puntaje('vix'), puntaje('credit'))],\r\n    ['Liquidez', liquidez],\r\n    ['Tasas e Inflación', Math.max(puntaje('treasury10y'), puntaje('inflation'), puntaje('diesel'))],\r\n    ['Empleo y Condiciones Financieras', Math.max(puntaje('claims'), puntaje('consumer'), puntaje('payrolls'), puntaje('nfci'))]\r\n  ].filter(([, valor]) => valor >= 45).map(([nombre]) => nombre);\r\n  const urgente = radar >= 70 && areas.length >= 3;\r\n  const encabezado = urgente ? 'Atención Urgente' : radar >= 60 ? 'Tensión Elevada' : radar >= 30 ? 'Entorno de Atención' : 'Entorno Tranquilo';\r\n  const nivel = $('level'), titulo = $('rtitle'), lectura = $('rtext');\r\n  if (nivel) nivel.textContent = encabezado;\r\n  if (titulo) titulo.textContent = encabezado;\r\n  if (lectura) lectura.textContent = urgente\r\n    ? `El radar alcanza ${radar}/100 y hay tensión simultánea en ${areas.length} áreas: ${areas.join(', ')}. Conviene revisar las fuentes y el contexto antes de sacar conclusiones.`\r\n    : `El radar marca ${radar}/100. La alerta urgente requiere 70 o más y tensión simultánea en al menos tres áreas. Áreas bajo observación ahora: ${areas.length ? areas.join(', ') : 'ninguna'}.`;\r\n  const contenedor = document.querySelector('.radar-summary');\r\n  if (contenedor) {\r\n    let aviso = $('urgentReview');\r\n    if (!aviso) { aviso = document.createElement('div'); aviso.id = 'urgentReview'; aviso.className = 'urgent-review'; contenedor.append(aviso); }\r\n    aviso.classList.toggle('urgent', urgente);\r\n    aviso.innerHTML = urgente\r\n      ? '<b>Regla activada:</b> Atención Urgente. No es una predicción ni una instrucción financiera; es una prioridad de revisión.'\r\n      : '<b>Regla de Atención Urgente:</b> radar de 70/100 o más, con tensión simultánea en tres de estas áreas: Riesgo y Crédito, Liquidez, Tasas e Inflación, Empleo y Condiciones Financieras.';\r\n  }\r\n};\r\n</script><style>\r\n/* Rediseño editorial: una superficie de análisis, no una colección de tarjetas genéricas. */\r\n:root{--bg:#e8eff2;--p:#ffffff;--p2:#f5f8f9;--l:#c9d7dc;--t:#102c37;--m:#58707a;--teal:#0c6972;--amber:#9a6410;--red:#b42318;--sh:none}\r\nhtml[data-theme=dark]{--bg:#0c1820;--p:#102530;--p2:#162e3a;--l:#35505b;--t:#edf5f4;--m:#a9bcc2;--teal:#65c9c3;--amber:#f2ba57;--red:#ff8f82}\r\nbody{background:var(--bg);font-family:Arial,\"Helvetica Neue\",sans-serif;letter-spacing:.003em}\r\nmain{max-width:1440px;padding:34px 34px 72px}\r\n.top{padding:0 0 24px!important;border-bottom:1px solid var(--l);margin-bottom:18px!important}\r\n.top h1{font-family:Georgia,\"Times New Roman\",serif;font-size:clamp(2.25rem,4.3vw,3.7rem);font-weight:700;letter-spacing:-.04em;line-height:.95;text-transform:uppercase}\r\n.top .ey{color:var(--teal);font-size:.72rem;letter-spacing:.08em;text-transform:none;font-weight:700}\r\n.top .sub{margin-top:11px;font-size:1rem}\r\n.button,.stamp{border-radius:3px;padding:9px 11px;font-size:.78rem;box-shadow:none}.stamp{background:transparent}\r\n.notice{border:1px solid var(--l);border-left:3px solid var(--amber);border-radius:3px;background:var(--p);padding:13px 16px;margin:18px 0}\r\n.tabs{gap:0;border-bottom:1px solid var(--l);margin:0 0 24px}.tab{border:0;border-radius:0;background:transparent;padding:12px 16px;color:var(--m);font-size:.78rem;font-weight:700;letter-spacing:.045em}.tab[aria-selected=true]{background:transparent!important;border-bottom:3px solid var(--teal)!important;color:var(--t)!important}.tab:hover{border-color:transparent;color:var(--teal)}\r\n.grid{gap:18px}.card{border:1px solid var(--l);border-radius:4px;box-shadow:none;background:var(--p);padding:20px}.head{padding-bottom:14px;border-bottom:1px solid var(--l);margin-bottom:14px}.head h2{font-family:Georgia,\"Times New Roman\",serif;font-size:1.22rem;letter-spacing:-.01em}\r\n.radar{gap:18px}.radar-block{border-radius:4px;background:var(--p);padding:20px}.radar-score{border-top:4px solid var(--teal)}.radar-summary{border-top:4px solid var(--amber)}.radar-context{border-top:4px solid #6b8791}.radar-context h2,.radar-summary h2{font-family:Georgia,\"Times New Roman\",serif}.radar-summary #rtext{text-align:left;line-height:1.68}\r\n.chart{border:1px solid var(--l);border-radius:3px;box-shadow:none;background:var(--p);padding:16px}.chart .ct{padding-bottom:10px;border-bottom:1px solid var(--l)}.chart h3{font-family:Georgia,\"Times New Roman\",serif;font-size:1.02rem;line-height:1.25}.value{font-family:Georgia,\"Times New Roman\",serif;font-size:2rem!important;letter-spacing:-.04em}.note{font-size:.83rem}.traffic{border-radius:2px;font-size:.68rem;font-weight:700;padding:4px 6px}.plot{margin-top:13px}.foot{border-top:1px solid var(--l);padding-top:8px;color:var(--m)}\r\n.indicator-pages{border-bottom:1px solid var(--l);gap:0;margin-bottom:16px}.indicator-pages .tab{padding-left:0;padding-right:22px}.indicator-page-note{font-size:.92rem;color:var(--m)}\r\n.signals{box-shadow:none}.signals th{background:var(--p2);font-size:.69rem;letter-spacing:.06em}.signals td{padding:13px 8px}.signals tr+tr td{border-top:1px solid var(--l)}\r\n.guide-page .card{max-width:1000px;margin:0 auto 18px}.guide-page h2,.reading-note h2{font-family:Georgia,\"Times New Roman\",serif;font-size:1.8rem;letter-spacing:-.02em}.callout{border-left:3px solid var(--teal);border-radius:0;background:var(--p2);padding:14px 16px}.example{border-left-color:var(--amber);border-radius:0}\r\n.urgent-review{border-radius:3px}.footer{border-top:1px solid var(--l);padding-top:18px;margin-top:28px}\r\n@media(max-width:760px){main{padding:24px 16px 48px}.top h1{font-size:2.35rem}.tab{padding:11px 9px;font-size:.68rem}.card,.radar-block{padding:16px}.grid{gap:12px}}\r\n</style><style>\r\n.urgent-banner{display:grid;grid-template-columns:auto 1fr auto;gap:16px;align-items:center;margin:18px 0 22px;padding:17px 20px;border:1px solid #a51c16;border-left:7px solid #a51c16;background:#fff3f2;color:#751b16}.urgent-banner[hidden]{display:none}.urgent-banner .alert-mark{display:grid;place-items:center;width:36px;height:36px;border-radius:50%;background:#a51c16;color:#fff;font-size:1.35rem;font-weight:800}.urgent-banner strong{display:block;font-size:1rem;letter-spacing:.06em}.urgent-banner span{display:block;margin-top:4px;font-size:.9rem;line-height:1.45}.urgent-banner small{font-size:.78rem;text-align:right;line-height:1.4;color:#7f1d1d}@media(max-width:760px){.urgent-banner{grid-template-columns:auto 1fr}.urgent-banner small{grid-column:1/-1;text-align:left}}html[data-theme=dark] .urgent-banner{background:#38191e;border-color:#ff8f82;color:#ffe3df}html[data-theme=dark] .urgent-banner small{color:#ffd2cb}\r\n</style><script>\r\n/* Cuando la regla se activa, la alerta se ve antes de cualquier gráfico. */\r\nconst actualizarAlertaEditorial = overall;\r\noverall = function () {\r\n  actualizarAlertaEditorial();\r\n  const resumenAlerta = $('urgentReview');\r\n  const activa = resumenAlerta?.classList.contains('urgent');\r\n  let franja = $('urgentBanner');\r\n  if (!franja) {\r\n    franja = document.createElement('aside');\r\n    franja.id = 'urgentBanner';\r\n    franja.className = 'urgent-banner';\r\n    franja.setAttribute('role','status');\r\n    document.querySelector('.notice')?.insertAdjacentElement('afterend', franja);\r\n  }\r\n  franja.hidden = !activa;\r\n  if (activa) {\r\n    const lectura = $('rtext')?.textContent || '';\r\n    const puntaje = lectura.match(/\\b\\d{1,3}\\/100\\b/)?.[0] || '70/100 o más';\r\n    const areas = lectura.split('áreas: ')[1]?.replace(/\\.\\s*Conviene[\\s\\S]*/, '') || 'varias áreas del tablero';\r\n    franja.innerHTML = `<div class=\"alert-mark\">!</div><div><strong>ATENCIÓN URGENTE · RADAR ${puntaje}</strong><span>Coinciden señales en: ${areas}.</span></div><small>Revisar fuentes y contexto.<br>No es una instrucción financiera.</small>`;\r\n  }\r\n};\r\n</script><style>\r\n/* Fase 2: jerarquía de lectura. Las tres señales principales dominan;\r\n   las otras tres aportan contexto sin competir visualmente. */\r\n.charts{grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;align-items:start}\r\n.chart[data-rank=\"lead\"]{background:var(--p);border-top:4px solid var(--teal);padding:18px 18px 16px}\r\n.chart[data-rank=\"lead\"] .plot{height:184px}\r\n.chart[data-rank=\"lead\"] .value{font-size:2.28rem!important}\r\n.chart[data-rank=\"context\"]{background:transparent;border-color:var(--l);padding:15px 16px 13px}\r\n.chart[data-rank=\"context\"] .plot{height:128px}\r\n.chart[data-rank=\"context\"] .value{font-size:1.78rem!important}\r\n.chart[data-rank=\"context\"] .ct{border-bottom-style:dashed}\r\n.chart[data-rank=\"context\"] .foot{font-size:.66rem}\r\n.chart[data-rank=\"context\"] .note{min-height:2.4em}\r\n.chart[data-rank=\"lead\"] h3{font-size:1.12rem}\r\n.chart[data-rank=\"context\"] h3{font-size:.96rem}\r\n.chart[data-rank=\"lead\"] .traffic{font-size:.71rem}\r\n.charts::after{content:\"\";grid-column:1/-1;height:0;order:99}\r\n.indicator-page-note{border-left:3px solid var(--teal);padding:5px 0 5px 11px;margin:4px 0 18px;font-size:.9rem;max-width:760px}\r\n.signals .traffic{vertical-align:middle;margin-right:7px}\r\n@media(max-width:900px){.charts{grid-template-columns:repeat(2,minmax(0,1fr))}.chart[data-rank=\"lead\"] .plot{height:166px}}\r\n@media(max-width:620px){.charts{grid-template-columns:1fr}.chart[data-rank=\"lead\"] .plot{height:176px}.chart[data-rank=\"context\"] .plot{height:145px}}\r\n</style><script>\r\n/* La estructura se aplica tras cada actualización de datos o cambio de período. */\r\nconst dibujarJerarquiaProfesional = draw;\r\ndraw = function () {\r\n  dibujarJerarquiaProfesional();\r\n  const principales = new Set(['vix','credit','treasury10y','rrp','tga','reserves']);\r\n  const tablero = $('charts');\r\n  if (!tablero) return;\r\n  Array.from(tablero.querySelectorAll('.chart')).forEach((tarjeta) => {\r\n    const clave = tarjeta.querySelector('.plot')?.dataset.k;\r\n    if (!clave) {\r\n      /* La tarjeta Hogares: precios y confianza era una nota sin dato ni gráfico. */\r\n      tarjeta.remove();\r\n      return;\r\n    }\r\n    tarjeta.dataset.rank = principales.has(clave) ? 'lead' : 'context';\r\n  });\r\n};\r\n</script><style>\r\n/* Fase 3: lenguaje visual de una mesa de análisis, sobrio y orientado a lectura. */\r\n:root{--bg:#dfe9ec;--p:#fbfcfc;--p2:#f1f6f7;--l:#b9cbd1;--t:#142c35;--m:#506a74;--teal:#006b73;--amber:#9a6200;--red:#ae2c25}\r\nbody{background:var(--bg);font-family:\"Segoe UI Variable Text\",\"Aptos\",\"Segoe UI\",sans-serif}\r\nmain{max-width:1520px;background:#f7fafb;margin:28px auto 0;padding:38px 42px 74px;border:1px solid #c3d2d7}\r\n.top{padding:8px 0 28px!important;margin-bottom:0!important;border-bottom:2px solid var(--t)}\r\n.top h1{font-family:Cambria,Georgia,serif;font-size:clamp(2.35rem,4.6vw,4.25rem);font-weight:700;letter-spacing:-.052em;line-height:.9}\r\n.top .sub{font-size:1.02rem;max-width:680px;margin-left:auto;margin-right:auto}.top .ey{font-size:.68rem;letter-spacing:.1em}\r\n.stamp{font-variant-numeric:tabular-nums;border-color:var(--l)}\r\n.notice{margin:20px 0 0;border-left-width:5px;background:#fffdf8;font-size:.96rem}\r\n.tabs{margin:0 0 22px;padding-top:10px}.tab{font-family:\"Segoe UI Variable Text\",\"Aptos\",\"Segoe UI\",sans-serif}\r\n.grid{gap:22px}.card{border-radius:6px}.radar{gap:16px}.radar-block{padding:22px;border-radius:5px}.radar-score{background:#f9fbfb}.radar-summary{background:#fffdf9}.radar-context{background:#f5f8f9}\r\n.dashboard>.card.s12>.head{align-items:end}.dashboard .head h2{font-family:Cambria,Georgia,serif;font-size:1.45rem;letter-spacing:-.025em;text-transform:none}.dashboard .head p{max-width:760px}\r\n.charts{gap:20px}.chart{border-radius:5px}.chart[data-rank=\"lead\"]{border-top-width:5px;box-shadow:0 1px 0 #8da8b0}.chart[data-rank=\"context\"]{background:#f7fafb;border-color:#c7d5da}.chart h3{font-family:\"Segoe UI Variable Text\",\"Aptos\",\"Segoe UI\",sans-serif;font-weight:750}.value{font-variant-numeric:tabular-nums}.var,.foot{font-variant-numeric:tabular-nums}\r\n.fact{border-radius:2px;border-color:transparent;padding:3px 0;text-decoration:underline;text-underline-offset:3px;font-size:.73rem}.fact:hover{background:transparent;color:var(--t)}\r\n.signals{font-size:.9rem}.signals th{background:#e9f0f2}.signals tr:hover td{background:#f2f7f8}.footer{font-size:.76rem}\r\ndialog{max-width:880px;border-radius:6px;padding:30px 34px;box-shadow:0 28px 80px #081b244d}.dialog-close{border-radius:3px}.dialog-body{margin-top:6px}.dialog-body h2{font-family:Cambria,Georgia,serif;font-size:2rem;letter-spacing:-.025em;max-width:28ch}.dialog-body h3{font-family:Cambria,Georgia,serif;font-size:1.08rem;margin:0 0 7px}.dialog-body p{font-size:.98rem;line-height:1.68}.dialog-body b{color:var(--t)}\r\n.fact-kicker{margin:0 0 10px!important;color:var(--teal)!important;font-size:.76rem!important;font-weight:700;letter-spacing:.06em;text-transform:uppercase}.fact-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px 28px;margin:22px 0}.fact-grid section{border-top:1px solid var(--l);padding-top:12px}.fact-grid p{margin:0}.fact-example{border-left:4px solid var(--amber);background:#fffaf0;padding:14px 16px;margin:18px 0}.fact-source{font-size:.9rem!important;color:var(--m)!important}.fact-source a{color:var(--teal);font-weight:700}.fact-limit{border-top:1px solid var(--l);padding-top:13px;font-size:.9rem!important;color:var(--m)!important}\r\n@media(max-width:760px){main{margin:0;border:0;padding:28px 17px 54px}.top h1{font-size:2.5rem}.fact-grid{grid-template-columns:1fr;gap:16px}.dialog-body h2{font-size:1.65rem}dialog{padding:23px 20px}}\r\n</style><script>\r\n/* Fichas ampliadas: una explicación útil para aprender, no solo una definición breve. */\r\nconst fichasProfesionales={\r\n vix:{t:'Índice de Volatilidad (Volatility Index, VIX)',d:'Es una medida de la volatilidad esperada a unos 30 días que se obtiene de los precios de opciones sobre el S&P 500. No mide directamente el precio de las acciones.',l:'Un VIX más alto suele significar que el coste de protección con opciones aumentó. Compáralo con su trayectoria reciente, no solo con un número aislado.',p:'Cuando el VIX sube junto con el Diferencial de Bonos de Alto Rendimiento, la cautela puede estar extendiéndose desde las acciones hacia el crédito.',r:'Ayuda a observar demanda de protección y nerviosismo del mercado.',f:'Diario · Cboe, distribuido por FRED.',u:'https://fred.stlouisfed.org/series/VIXCLS',x:'Puede aumentar por eventos puntuales y volver a bajar con rapidez. Por sí solo no predice una caída de la bolsa.'},\r\n credit:{t:'Diferencial Ajustado por Opciones de Bonos de Alto Rendimiento (High Yield OAS)',d:'Mide la compensación adicional que exigen los inversionistas para prestar a emisores de bonos con mayor riesgo, frente a una referencia de menor riesgo.',l:'Cuando se amplía, el mercado exige mayor prima por riesgo. Una subida persistente suele ser más relevante que una variación de un solo día.',p:'Si el diferencial se amplía mientras el VIX sube, ambos pueden señalar una mayor aversión al riesgo. La lectura mejora al compararlos durante varias semanas.',r:'Aporta una lectura directa de las condiciones de crédito corporativo.',f:'Diario · ICE BofA, distribuido por FRED.',u:'https://fred.stlouisfed.org/series/BAMLH0A0HYM2',x:'No identifica por sí mismo qué empresa o sector tendrá problemas; resume un segmento amplio del mercado.'},\r\n treasury10y:{t:'Rendimiento del Bono del Tesoro de Estados Unidos a 10 Años (U.S. Treasury 10-Year Yield)',d:'Es el rendimiento anual exigido por el mercado para mantener un bono del Tesoro estadounidense con vencimiento cercano a diez años.',l:'Incorpora expectativas de inflación, crecimiento, política monetaria y compensación por plazo. No es la tasa oficial fijada por la Reserva Federal.',p:'Si el rendimiento permanece alto, hipotecas y financiación empresarial pueden encarecerse; el efecto final depende de los márgenes de cada prestamista.',r:'Sirve de referencia para las condiciones de financiación de largo plazo.',f:'Diario · Departamento del Tesoro, distribuido por FRED.',u:'https://fred.stlouisfed.org/series/DGS10',x:'Un rendimiento alto no tiene una sola explicación: puede reflejar crecimiento sólido, inflación esperada o cambios en la demanda de bonos.'},\r\n inflation:{t:'Inflación Anual de Precios al Consumidor (Consumer Price Index, CPI)',d:'Compara el índice general de precios al consumidor con el mismo mes del año previo. El tablero calcula esa variación anual a partir de la serie mensual.',l:'Muestra el ritmo de cambio de precios, no el nivel de precios ni la experiencia exacta de cada hogar.',p:'Un aumento sostenido de energía y transporte puede presionar algunos precios. Para interpretar la inflación conviene contrastar también salarios, consumo y medidas subyacentes.',r:'Ayuda a contextualizar poder de compra y posibles condiciones monetarias restrictivas.',f:'Mensual · Oficina de Estadísticas Laborales de Estados Unidos (BLS), distribuido por FRED.',u:'https://fred.stlouisfed.org/series/CPIAUCSL',x:'Las cifras mensuales pueden revisarse y la variación anual no permite inferir una causa única.'},\r\n diesel:{t:'Precio Minorista del Diésel en Estados Unidos (U.S. Retail Diesel Price)',d:'Es el precio promedio minorista semanal del diésel en Estados Unidos. Es un insumo relevante para transporte terrestre, logística, agricultura y parte de la actividad industrial.',l:'La alerta del tablero mira la velocidad del cambio, porque un salto rápido puede importar más que un nivel estable.',p:'Si el diésel aumenta con rapidez, transportar mercancías puede encarecerse. Algunas empresas podrían trasladar parte del coste a precios, aunque no es automático.',r:'Aporta una señal de costes físicos dentro del circuito económico.',f:'Semanal · Administración de Información Energética de Estados Unidos (EIA), distribuido por FRED.',u:'https://fred.stlouisfed.org/series/GASDESW',x:'Es un promedio nacional y no representa el precio específico de cada región o combustible.'},\r\n rrp:{t:'Acuerdo de Recompra Inversa Nocturno (Overnight Reverse Repurchase Agreement, ON RRP)',d:'Es una herramienta de política monetaria mediante la cual la Reserva Federal realiza operaciones garantizadas de muy corto plazo con instituciones elegibles para gestionar liquidez y apoyar el control de tasas de interés.',l:'Al cierre del Día 1, una institución entrega efectivo y recibe temporalmente títulos como garantía. El Día 2, la Reserva Federal recompra los títulos y paga la tasa acordada.',p:'Un cambio notable del ON RRP se interpreta junto con Reservas Bancarias y la Cuenta General del Tesoro. Es una lectura de la estructura de liquidez, no una alarma aislada.',r:'Ayuda a observar cómo se mueve efectivo de muy corto plazo dentro del sistema financiero.',f:'Diario · Reserva Federal de Nueva York, distribuido por FRED.',u:'https://fred.stlouisfed.org/series/RRPONTSYD',x:'No representa toda la liquidez de la economía ni determina por sí solo la dirección de las tasas privadas.'},\r\n tga:{t:'Cuenta General del Tesoro (Treasury General Account, TGA)',d:'Es la cuenta operativa principal del Departamento del Tesoro de Estados Unidos. Desde ella se reciben y realizan pagos federales.',l:'Sus variaciones pueden cambiar temporalmente dónde se encuentra el efectivo en el sistema financiero. Se lee en conjunto con Reservas Bancarias y operaciones de la Reserva Federal.',p:'Si el saldo de la Cuenta General del Tesoro aumenta y las Reservas Bancarias bajan, conviene revisar el contexto de pagos, recaudación y otras fuentes de liquidez.',r:'Permite seguir un componente operativo importante de la liquidez del Tesoro.',f:'Semanal · Departamento del Tesoro, distribuido por FRED.',u:'https://fred.stlouisfed.org/series/WTREGEN',x:'Un cambio de saldo puede obedecer a operaciones normales del Tesoro y no equivale automáticamente a tensión financiera.'},\r\n reserves:{t:'Reservas Bancarias (Bank Reserves)',d:'Son los saldos que las instituciones depositarias mantienen en la Reserva Federal. Forman parte de la infraestructura de pagos y de la liquidez bancaria.',l:'Una tendencia debe leerse junto con la Cuenta General del Tesoro, el ON RRP y las condiciones de crédito. El nivel adecuado cambia con el tiempo y con la regulación.',p:'Una caída de reservas junto con otras señales de liquidez puede justificar una revisión más detallada, pero no confirma por sí sola una restricción de crédito.',r:'Describe una parte central de la plomería financiera estadounidense.',f:'Semanal · Reserva Federal, distribuido por FRED.',u:'https://fred.stlouisfed.org/series/WRESBAL',x:'No mide directamente cuánto crédito recibe una empresa o un hogar.'},\r\n claims:{t:'Solicitudes Iniciales de Desempleo (Initial Jobless Claims)',d:'Cuenta las nuevas solicitudes semanales de seguro de desempleo, ajustadas por estacionalidad. Es una de las lecturas laborales más oportunas.',l:'Lo importante suele ser la tendencia de varias semanas, pues una semana individual puede estar afectada por calendario, clima o factores administrativos.',p:'Si las solicitudes aumentan de manera persistente y la creación de empleo se debilita, merece revisarse el mercado laboral con mayor atención.',r:'Ofrece una señal temprana sobre posibles cambios en el empleo.',f:'Semanal · Departamento de Trabajo de Estados Unidos, distribuido por FRED.',u:'https://fred.stlouisfed.org/series/ICSA',x:'No equivale a la tasa de desempleo ni resume todo el mercado laboral.'},\r\n consumer:{t:'Sentimiento del Consumidor (Consumer Sentiment)',d:'Es una encuesta mensual que recoge cómo los hogares perciben su situación financiera y las perspectivas económicas.',l:'No es una medición directa de producción, inflación o empleo. Expresa percepciones, que pueden cambiar con noticias, precios y experiencias personales.',p:'Inflación alta junto con un sentimiento en descenso puede sugerir presión sobre los hogares. La coincidencia describe un contexto; no demuestra causalidad por sí sola.',r:'Complementa los datos objetivos con la percepción de los hogares.',f:'Mensual · Universidad de Míchigan, distribuido por FRED.',u:'https://fred.stlouisfed.org/series/UMCSENT',x:'El sentimiento puede divergir de otros datos económicos durante períodos prolongados.'},\r\n payrolls:{t:'Variación del Empleo No Agrícola (Nonfarm Payrolls)',d:'Mide el cambio mensual del empleo asalariado no agrícola en Estados Unidos. El tablero calcula la variación mensual de la serie de empleo total.',l:'Las cifras iniciales pueden revisarse. Conviene compararlas con Solicitudes Iniciales de Desempleo, salarios, participación laboral y revisiones previas.',p:'Una desaceleración de creación de empleo, acompañada por solicitudes de desempleo crecientes, puede justificar una lectura laboral más cautelosa.',r:'Es una referencia mensual amplia sobre la creación o pérdida de puestos de trabajo.',f:'Mensual · Oficina de Estadísticas Laborales de Estados Unidos (BLS), distribuido por FRED.',u:'https://fred.stlouisfed.org/series/PAYEMS',x:'No incluye agricultura y no debe interpretarse sin tener en cuenta revisiones y composición sectorial.'},\r\n nfci:{t:'Índice Nacional de Condiciones Financieras (National Financial Conditions Index, NFCI)',d:'Resume semanalmente información de riesgo, crédito y liquidez de los mercados financieros estadounidenses frente a sus promedios históricos.',l:'Valores por encima de cero suelen asociarse con condiciones más restrictivas; valores negativos, con condiciones más holgadas. Es una medida compuesta.',p:'Si el NFCI aumenta al mismo tiempo que suben el VIX y el Diferencial de Alto Rendimiento, varias fuentes pueden estar describiendo un entorno financiero más exigente.',r:'Reúne en una sola lectura componentes de las condiciones financieras.',f:'Semanal · Reserva Federal de Chicago.',u:'https://www.chicagofed.org/research/data/nfci/current-data',x:'Por ser un índice compuesto, no sustituye revisar los indicadores individuales que lo acompañan.'}\r\n};\r\nfunction abrirFichaProfesional(clave){\r\n  const x=fichasProfesionales[clave]; if(!x)return;\r\n  $('factBody').innerHTML=`<p class=\"fact-kicker\">Ficha educativa del indicador</p><h2>${x.t}</h2><div class=\"fact-grid\"><section><h3>Qué es</h3><p>${x.d}</p></section><section><h3>Cómo leerlo</h3><p>${x.l}</p></section><section><h3>Por qué importa</h3><p>${x.r}</p></section><section><h3>Fuente y frecuencia</h3><p>${x.f}</p></section></div><section class=\"fact-example\"><h3>Ejemplo de lectura</h3><p>${x.p}</p></section><p class=\"fact-limit\"><b>Límite de interpretación:</b> ${x.x}</p><p class=\"fact-source\"><a href=\"${x.u}\" target=\"_blank\" rel=\"noopener\">Consultar la fuente pública del indicador</a></p>`;\r\n  if(!$('factDialog').open)$('factDialog').showModal();\r\n}\r\ndocument.addEventListener('click',(evento)=>{\r\n  const boton=evento.target.closest('.fact'); if(!boton)return;\r\n  const clave=boton.closest('.chart')?.querySelector('.plot')?.dataset.k;\r\n  if(!clave)return; evento.preventDefault(); evento.stopImmediatePropagation(); abrirFichaProfesional(clave);\r\n},true);\r\n</script><style>\r\n/* Firma editorial del observatorio: una identidad discreta, sin desplazar el tablero. */\r\n.top{position:relative}.brand-identity{position:absolute;left:0;top:8px;display:flex;align-items:center;gap:10px;text-align:left;color:var(--t)}\r\n.brand-monogram{display:grid;place-items:center;width:31px;height:31px;border:2px solid var(--teal);font-family:Cambria,Georgia,serif;font-size:.82rem;font-weight:700;letter-spacing:-.08em;color:var(--teal)}\r\n.brand-copy{display:grid;gap:2px}.brand-copy strong{font-size:.69rem;letter-spacing:.075em}.brand-copy span{font-size:.66rem;line-height:1.25;color:var(--m);max-width:190px}\r\n.top .sub{max-width:760px}.publication-line{display:flex;justify-content:center;gap:20px;flex-wrap:wrap;margin:16px 0 0;color:var(--m);font-size:.78rem}.publication-line span{display:flex;align-items:center;gap:7px}.publication-line i{display:inline-block;width:5px;height:5px;border-radius:50%;background:var(--teal)}\r\n@media(max-width:860px){.brand-identity{position:static;justify-content:center;margin:0 0 16px}.publication-line{gap:12px}}@media(max-width:560px){.brand-copy span{display:none}.publication-line{font-size:.72rem}}\r\n</style><script>\r\n/* El encabezado identifica el producto como un observatorio educativo, no como una página promocional. */\r\nconst encabezadoEditorial=document.querySelector('.top');\r\nconst bloqueTitulo=encabezadoEditorial?.querySelector('div');\r\nif(encabezadoEditorial&&bloqueTitulo&&!encabezadoEditorial.querySelector('.brand-identity')){\r\n  const firma=document.createElement('div');\r\n  firma.className='brand-identity';\r\n  firma.innerHTML='<span class=\"brand-monogram\" aria-hidden=\"true\">RM</span><span class=\"brand-copy\"><strong>OBSERVATORIO RM</strong><span>Condiciones de mercado y economía</span></span>';\r\n  encabezadoEditorial.append(firma);\r\n  const subtitulo=bloqueTitulo.querySelector('.sub');\r\n  if(subtitulo) subtitulo.textContent='Observatorio educativo de riesgo, crédito, liquidez, precios y actividad económica.';\r\n  const linea=document.createElement('div');\r\n  linea.className='publication-line';\r\n  linea.innerHTML='<span><i></i>Doce indicadores públicos</span><span><i></i>Lectura de contexto</span><span><i></i>Sin recomendaciones de inversión</span>';\r\n  bloqueTitulo.append(linea);\r\n}\r\n</script><style>\r\n/* El tablero se publica con una sola superficie clara y contrastada. */\r\nhtml,html[data-theme=\"dark\"]{color-scheme:light;--bg:#dfe9ec;--p:#fbfcfc;--p2:#f1f6f7;--l:#b9cbd1;--t:#142c35;--m:#506a74;--teal:#006b73;--amber:#9a6200;--red:#ae2c25}\r\nhtml[data-theme=\"dark\"] .urgent-banner{background:#fff3f2;border-color:#a51c16;color:#751b16}html[data-theme=\"dark\"] .urgent-banner small{color:#7f1d1d}html[data-theme=\"dark\"] .urgent-review.urgent{background:#fef2f2;color:#7f1d1d}\r\n</style><script>\r\n/* El tema definitivo se restablece al final, después de cargar todos los estilos. */\r\n</script><style>\r\n/* Modo oscuro funcional: superficie, texto, controles y gráficos conservan contraste alto. */\r\nhtml[data-theme=\"dark\"]{color-scheme:dark;--bg:#0d1b20;--p:#14252b;--p2:#1a2d34;--l:#3d5961;--t:#f0f7f7;--m:#bdd0d3;--teal:#63d2ca;--amber:#f4c66a;--red:#ff9588}\r\nhtml[data-theme=\"dark\"] body{background:#0d1b20}html[data-theme=\"dark\"] main{background:#101f25;border-color:#36515a}html[data-theme=\"dark\"] .notice{background:#18282e;border-color:#526a71;color:var(--t)}\r\nhtml[data-theme=\"dark\"] .radar-score{background:#14252b}html[data-theme=\"dark\"] .radar-summary{background:#1c2929}html[data-theme=\"dark\"] .radar-context{background:#16272e}html[data-theme=\"dark\"] .chart[data-rank=\"context\"]{background:#122228;border-color:#3a555d}\r\nhtml[data-theme=\"dark\"] .signals th{background:#21363d}html[data-theme=\"dark\"] .signals tr:hover td{background:#1a2e35}html[data-theme=\"dark\"] .fact-example{background:#2d2617;color:var(--t)}html[data-theme=\"dark\"] dialog{background:#14252b;border-color:#466069}\r\nhtml[data-theme=\"dark\"] .urgent-banner{background:#3b1e20;border-color:#ff9588;color:#ffe8e4}html[data-theme=\"dark\"] .urgent-banner small{color:#ffd2cb}html[data-theme=\"dark\"] .urgent-review.urgent{background:#3b1e20;color:#ffe8e4}\r\n</style><script>\r\n/* El usuario puede elegir el fondo; ambos temas se muestran con contraste comprobable. */\r\nconst accionesCabecera=document.querySelector('.top .actions');\r\nlet botonTema=$('theme');\r\nif(!botonTema&&accionesCabecera){botonTema=document.createElement('button');botonTema.id='theme';botonTema.type='button';botonTema.className='button';accionesCabecera.prepend(botonTema)}\r\nfunction aplicarTemaLegible(valor){\r\n  const tema=valor==='dark'?'dark':'light';\r\n  document.documentElement.dataset.theme=tema;\r\n  localStorage.setItem('radar-theme',tema);\r\n  if(botonTema)botonTema.textContent=tema==='dark'?'Usar fondo claro':'Usar fondo oscuro';\r\n}\r\naplicarTemaLegible(localStorage.getItem('radar-theme')||'light');\r\nif(botonTema)botonTema.onclick=()=>aplicarTemaLegible(document.documentElement.dataset.theme==='light'?'dark':'light');\r\n</script><style>\r\n/* Consulta institucional: contexto de política económica, fuera del puntaje del radar. */\r\n.policy-brief{padding:0!important;overflow:hidden}.policy-heading{display:flex;justify-content:space-between;gap:18px;align-items:end;padding:20px 22px 17px;border-bottom:1px solid var(--l)}.policy-heading h2{font-family:Cambria,Georgia,serif;font-size:1.45rem;letter-spacing:-.025em}.policy-heading p{max-width:660px}.policy-date{font-size:.76rem;color:var(--m);white-space:nowrap}\r\n.fomc-layout{display:grid;grid-template-columns:1.05fr 1.25fr .9fr;gap:0}.fomc-layout>section{padding:21px 22px;min-width:0}.fomc-layout>section+section{border-left:1px solid var(--l)}.policy-label{margin:0 0 8px;color:var(--teal);font-size:.73rem;font-weight:750;letter-spacing:.06em;text-transform:uppercase}.fomc-next-date{font-family:Cambria,Georgia,serif;font-size:1.8rem;color:var(--t);line-height:1.05}.fomc-layout h3{font-family:Cambria,Georgia,serif;font-size:1.08rem;margin:0 0 7px}.fomc-layout p{font-size:.92rem}.fomc-decision{background:var(--p2)}.fomc-rate{font-family:Cambria,Georgia,serif;font-size:1.45rem;font-weight:700;color:var(--teal);margin:8px 0}.policy-links{display:grid;gap:8px}.policy-links a{display:block;border:1px solid var(--l);padding:9px 10px;color:var(--t);font-size:.84rem;font-weight:700;text-decoration:none}.policy-links a:hover{border-color:var(--teal);color:var(--teal)}\r\n.institutions-strip{border-top:1px solid var(--l);padding:20px 22px 23px}.institutions-strip h3{font-family:Cambria,Georgia,serif;margin:0 0 13px;font-size:1.08rem}.institution-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.institution-card{border-left:3px solid var(--teal);padding:0 0 0 12px}.institution-card:nth-child(2){border-left-color:var(--amber)}.institution-card:nth-child(3){border-left-color:#6b8791}.institution-card h4{margin:0 0 6px;font-size:.96rem}.institution-card p{font-size:.88rem}.institution-card a{color:var(--teal);font-weight:700}\r\nhtml[data-theme=\"dark\"] .fomc-decision{background:#1a2d34}html[data-theme=\"dark\"] .policy-links a{color:var(--t);background:#14252b}html[data-theme=\"dark\"] .policy-links a:hover{color:var(--teal);border-color:var(--teal)}\r\n@media(max-width:900px){.fomc-layout{grid-template-columns:1fr}.fomc-layout>section+section{border-left:0;border-top:1px solid var(--l)}.institution-cards{grid-template-columns:1fr}.policy-heading{display:block}.policy-date{display:block;margin-top:8px}.fomc-next-date{font-size:1.55rem}}\r\n</style><script>\r\n/* Información oficial de consulta; no altera semáforos ni el Radar de Atención. */\r\nconst tarjetaRadar=document.querySelector('.radar')?.closest('.card');\r\nif(tarjetaRadar&&!$('policyBrief')){\r\n  const consulta=document.createElement('article');\r\n  consulta.id='policyBrief';consulta.className='card s12 policy-brief';\r\n  consulta.innerHTML=`<header class=\"policy-heading\"><div><h2>Política económica de Estados Unidos</h2><p>Consulta institucional para interpretar el entorno. Esta información no modifica el Radar de Atención ni representa una recomendación financiera.</p></div><span class=\"policy-date\">Referencia: 3 de octubre de 2026</span></header>\r\n  <div class=\"fomc-layout\">\r\n    <section><p class=\"policy-label\">Próxima reunión del FOMC</p><p class=\"fomc-next-date\">27–28 oct. 2026</p><p style=\"margin-top:9px\">Reunión de dos días, con conferencia de prensa prevista. Las fechas futuras deben confirmarse siempre en el calendario oficial.</p></section>\r\n    <section class=\"fomc-decision\"><p class=\"policy-label\">Resultado de la última reunión</p><h3>16 de septiembre de 2026</h3><p>El Comité Federal de Mercado Abierto elevó el rango objetivo de la tasa de fondos federales en 0,25 puntos porcentuales.</p><p class=\"fomc-rate\">3,75%–4,00%</p><p>La decisión fue unánime. El comunicado indicó que la inflación permanecía elevada y que la actividad continuaba expandiéndose a un ritmo sólido.</p></section>\r\n    <section><p class=\"policy-label\">Documentos oficiales</p><nav class=\"policy-links\" aria-label=\"Consultas oficiales del FOMC\"><a href=\"https://www.federalreserve.gov/monetarypolicy/fomccalendars.htm\" target=\"_blank\" rel=\"noopener\">Calendario del FOMC</a><a href=\"https://www.federalreserve.gov/newsevents/pressreleases/monetary20260916a.htm\" target=\"_blank\" rel=\"noopener\">Último comunicado</a><a href=\"https://www.federalreserve.gov/monetarypolicy/fomcprojtabl20260916.htm\" target=\"_blank\" rel=\"noopener\">Proyecciones económicas</a></nav></section>\r\n  </div>\r\n  <section class=\"institutions-strip\"><h3>Tres centros influyentes, tres funciones diferentes</h3><div class=\"institution-cards\">\r\n    <article class=\"institution-card\"><h4>Reserva Federal (Federal Reserve)</h4><p>Conduce la política monetaria mediante el FOMC, influye en las tasas de corto plazo, supervisa partes del sistema financiero y busca máximo empleo y estabilidad de precios.</p><a href=\"https://www.federalreserve.gov/aboutthefed/fedexplained/monetary-policy.htm\" target=\"_blank\" rel=\"noopener\">Consultar funciones de la Fed</a></article>\r\n    <article class=\"institution-card\"><h4>Departamento del Tesoro (Department of the Treasury)</h4><p>Gestiona las finanzas del gobierno federal: pagos, deuda pública, recaudación, cuentas gubernamentales y parte de la infraestructura financiera.</p><a href=\"https://home.treasury.gov/about/general-information/role-of-the-treasury\" target=\"_blank\" rel=\"noopener\">Consultar funciones del Tesoro</a></article>\r\n    <article class=\"institution-card\"><h4>Consejo de Asesores Económicos (Council of Economic Advisers, CEA)</h4><p>Asesora al Presidente con análisis económico sobre política nacional e internacional. No fija tasas ni administra la deuda pública.</p><a href=\"https://www.whitehouse.gov/cea/\" target=\"_blank\" rel=\"noopener\">Consultar Consejo de Asesores Económicos</a></article>\r\n  </div></section>`;\r\n  tarjetaRadar.insertAdjacentElement('afterend',consulta);\r\n}\r\n</script><style>\r\n/* Mapa educativo de las palancas públicas que influyen en la economía. */\r\n.policy-guide{max-width:1050px;margin:0 auto}.policy-guide .card{margin-bottom:18px}.policy-guide h2{font-family:Cambria,Georgia,serif;font-size:1.8rem;letter-spacing:-.02em}.policy-map{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:20px 0}.policy-map article{border-top:4px solid var(--teal);background:var(--p2);padding:17px}.policy-map article:nth-child(2){border-top-color:var(--amber)}.policy-map article:nth-child(3){border-top-color:#6b8791}.policy-map h3{font-family:Cambria,Georgia,serif;font-size:1.13rem;margin:0 0 8px}.policy-map p{font-size:.94rem}.policy-map strong{color:var(--t)}.policy-chain{margin:20px 0;padding:16px 18px;border-left:4px solid var(--teal);background:var(--p2)}.policy-chain p{font-size:1rem}.policy-guide .limit{border-top:1px solid var(--l);padding-top:14px;margin-top:18px}@media(max-width:760px){.policy-map{grid-template-columns:1fr}.policy-guide h2{font-size:1.5rem}}\r\n</style><script>\r\n/* Nueva lectura educativa: las instituciones se explican por su función, no solo por su nombre. */\r\nconst menuGuia=document.querySelector('.guide-nav');\r\nconst guiaPrincipal=$('guide');\r\nif(menuGuia&&guiaPrincipal&&!$('policyGuide')){\r\n  const boton=document.createElement('button');\r\n  boton.type='button';boton.className='tab guide-tab';boton.dataset.guidePage='politica';boton.textContent='Cómo se maneja la economía';\r\n  menuGuia.append(boton);\r\n  const pagina=document.createElement('section');\r\n  pagina.id='policyGuide';pagina.className='guide-page policy-guide';pagina.dataset.page='politica';pagina.hidden=true;\r\n  pagina.innerHTML=`<article class=\"card\"><p class=\"ey\">Guía institucional</p><h2>Cómo influyen las instituciones públicas en la economía</h2><p>La economía de Estados Unidos no se administra con un único botón. Las decisiones públicas, el Congreso, las empresas, los hogares, los bancos y los mercados interactúan entre sí. Este mapa distingue tres centros que influyen de manera importante, pero mediante palancas diferentes.</p><div class=\"policy-map\"><article><h3>Reserva Federal</h3><p><strong>Palanca:</strong> política monetaria.</p><p>El FOMC define la orientación de las tasas de corto plazo y la Fed implementa operaciones que influyen en dinero, crédito y condiciones financieras.</p><p><strong>Puede afectar:</strong> tasas, financiación, inversión, empleo e inflación, con retrasos y sin resultados garantizados.</p></article><article><h3>Departamento del Tesoro</h3><p><strong>Palanca:</strong> finanzas públicas.</p><p>Gestiona pagos, deuda pública, recaudación y la Cuenta General del Tesoro. Ejecuta las decisiones fiscales aprobadas por las instituciones políticas.</p><p><strong>Puede afectar:</strong> emisión de bonos, flujos de efectivo públicos y condiciones de liquidez operativa.</p></article><article><h3>Consejo de Asesores Económicos</h3><p><strong>Palanca:</strong> análisis y asesoría.</p><p>Prepara análisis para el Presidente sobre economía nacional e internacional. Ayuda a formular propuestas, pero no fija tasas ni ejecuta pagos públicos.</p><p><strong>Puede afectar:</strong> el diagnóstico y las prioridades de política económica de la Casa Blanca.</p></article></div></article><article class=\"card\"><h2>La cadena de decisión, en términos sencillos</h2><div class=\"policy-chain\"><p><strong>Datos públicos</strong> → hogares, empresas y autoridades interpretan la situación → la Fed ajusta su política monetaria cuando lo considera necesario → el Ejecutivo propone políticas → el Congreso aprueba leyes, presupuesto e impuestos → el Tesoro ejecuta pagos y financia al Gobierno.</p></div><p>Por eso no sería correcto decir que el CEA “maneja” la economía, ni que el Tesoro fija las tasas, ni que la Fed decide el presupuesto público. Cada institución opera dentro de reglas legales distintas y responde a objetivos diferentes.</p><p class=\"limit\"><strong>Cómo usar este tablero:</strong> el VIX y el crédito ayudan a observar cómo responde el mercado; el rendimiento del Tesoro y la inflación dan contexto para la política monetaria; el ON RRP, la Cuenta General del Tesoro y las Reservas Bancarias muestran parte de la infraestructura de liquidez. El calendario del FOMC añade el contexto de las decisiones programadas.</p></article>`;\r\n  guiaPrincipal.append(pagina);\r\n  boton.onclick=()=>{document.querySelectorAll('.guide-tab').forEach(x=>x.setAttribute('aria-selected',x===boton));document.querySelectorAll('.guide-page').forEach(x=>x.hidden=x!==pagina);scrollTo({top:0,behavior:'smooth'})};\r\n}\r\n</script><style>\r\n/* Pestaña independiente para política económica y proyecciones del FOMC. */\r\n.policy-page{max-width:1120px;margin:0 auto}.policy-page[hidden]{display:none}.policy-page .card{margin-bottom:18px}.policy-page h2{font-family:Cambria,Georgia,serif;font-size:1.85rem;letter-spacing:-.025em}.institution-nav{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:20px 0}.institution-nav button{border:1px solid var(--l);border-top:4px solid var(--teal);background:var(--p);padding:15px;text-align:left;color:var(--t);font:700 .95rem \"Segoe UI\",sans-serif;cursor:pointer}.institution-nav button:nth-child(2){border-top-color:var(--amber)}.institution-nav button:nth-child(3){border-top-color:#6b8791}.institution-nav button[aria-selected=true]{background:var(--p2);border-color:var(--teal)}.institution-detail{border-top:1px solid var(--l);padding-top:19px}.institution-detail[hidden]{display:none}.institution-detail h3{font-family:Cambria,Georgia,serif;font-size:1.35rem;margin:0 0 9px}.institution-detail p{max-width:88ch}.institution-detail a,.dot-source a{color:var(--teal);font-weight:700}.fomc-consultation{display:grid;grid-template-columns:1fr 1.4fr;gap:22px}.fomc-summary{padding:17px;border-left:4px solid var(--amber);background:var(--p2)}.fomc-summary h3{font-family:Cambria,Georgia,serif;margin:0 0 9px;font-size:1.18rem}.dotplot{border:1px solid var(--l);background:var(--p);padding:8px;overflow:auto}.dotplot svg{display:block;width:100%;min-width:680px;height:auto}.dotplot .gridline{stroke:var(--l);stroke-width:1}.dotplot .axis-label{fill:var(--m);font:12px \"Segoe UI\",sans-serif}.dotplot .year-label{fill:var(--t);font:700 13px \"Segoe UI\",sans-serif}.dotplot .dot{fill:var(--teal);stroke:var(--p);stroke-width:1}.dot-source{margin-top:10px;font-size:.87rem}@media(max-width:760px){.institution-nav,.fomc-consultation{grid-template-columns:1fr}.policy-page h2{font-size:1.55rem}}\r\n</style><script>\r\n/* La consulta FOMC sale del tablero y pasa a una pestaña educativa independiente. */\r\n$('policyBrief')?.remove();\r\nconst navegacionCompleta=document.querySelector('nav.tabs');\r\nconst paginaPolitica=document.createElement('section');\r\npaginaPolitica.id='politicaEconomica';paginaPolitica.className='policy-page';paginaPolitica.hidden=true;\r\npaginaPolitica.innerHTML=`<article class=\"card\"><p class=\"ey\">Guía institucional</p><h2>Política Económica de Estados Unidos</h2><p>Esta sección explica cómo distintas instituciones influyen en la economía. No son las únicas: el Presidente, el Congreso, las empresas, los hogares y los mercados también importan. Pero estas tres instituciones tienen funciones especialmente visibles dentro del tablero.</p><nav class=\"institution-nav\" aria-label=\"Instituciones económicas\"><button type=\"button\" data-office=\"fed\" aria-selected=\"true\">Reserva Federal<br><small>Política monetaria y crédito</small></button><button type=\"button\" data-office=\"treasury\" aria-selected=\"false\">Departamento del Tesoro<br><small>Deuda, pagos y finanzas públicas</small></button><button type=\"button\" data-office=\"cea\" aria-selected=\"false\">Consejo de Asesores Económicos<br><small>Análisis y asesoría presidencial</small></button></nav><section class=\"institution-detail\" data-office-detail=\"fed\"><h3>Reserva Federal (Federal Reserve)</h3><p>El Comité Federal de Mercado Abierto (FOMC) fija la orientación de la política monetaria, principalmente mediante el rango objetivo de la tasa de fondos federales. La Reserva Federal también implementa operaciones que influyen sobre reservas, dinero y crédito.</p><p><b>Conexión con este tablero:</b> rendimiento del Tesoro a 10 años, VIX, crédito, ON RRP y Reservas Bancarias ayudan a observar cómo se transmiten o se interpretan las condiciones monetarias.</p><a href=\"https://www.federalreserve.gov/aboutthefed/fedexplained/monetary-policy.htm\" target=\"_blank\" rel=\"noopener\">Abrir explicación oficial de la política monetaria</a></section><section class=\"institution-detail\" data-office-detail=\"treasury\" hidden><h3>Departamento del Tesoro (Department of the Treasury)</h3><p>Administra la financiación del Gobierno federal: recauda, realiza pagos, gestiona cuentas y emite deuda pública. Su Cuenta General del Tesoro (TGA) forma parte de la infraestructura de liquidez que se observa en este tablero.</p><p><b>Conexión con este tablero:</b> TGA, Reservas Bancarias y rendimientos del Tesoro muestran partes distintas del circuito entre operaciones públicas, mercados de deuda y sistema financiero.</p><a href=\"https://home.treasury.gov/about/general-information/role-of-the-treasury\" target=\"_blank\" rel=\"noopener\">Abrir funciones oficiales del Tesoro</a></section><section class=\"institution-detail\" data-office-detail=\"cea\" hidden><h3>Consejo de Asesores Económicos (Council of Economic Advisers, CEA)</h3><p>Es una oficina dentro de la Oficina Ejecutiva del Presidente. Analiza datos y asesora sobre política económica nacional e internacional. No fija tasas, no emite deuda y no administra pagos.</p><p><b>Conexión con este tablero:</b> sus análisis pueden usar datos de inflación, empleo, crecimiento y consumo como los que el tablero ayuda a contextualizar.</p><a href=\"https://www.whitehouse.gov/cea/\" target=\"_blank\" rel=\"noopener\">Abrir sitio oficial del Consejo de Asesores Económicos</a></section></article><article class=\"card\"><p class=\"ey\">Consulta FOMC</p><h2>Reuniones y proyecciones de tasas</h2><div class=\"fomc-consultation\"><div class=\"fomc-summary\"><h3>Próxima reunión</h3><p><b>27–28 de octubre de 2026</b></p><p style=\"margin-top:9px\">La última decisión, del 16 de septiembre, elevó el rango de fondos federales a 3,75%–4,00%.</p><p style=\"margin-top:12px\"><a href=\"https://www.federalreserve.gov/monetarypolicy/fomccalendars.htm\" target=\"_blank\" rel=\"noopener\">Consultar calendario oficial del FOMC</a><br><a href=\"https://www.federalreserve.gov/newsevents/pressreleases/monetary20260916a.htm\" target=\"_blank\" rel=\"noopener\">Consultar último comunicado oficial</a></p></div><div><h3 style=\"font-family:Cambria,Georgia,serif;margin:0 0 8px\">Proyecciones de tasas del FOMC (Dot Plot)</h3><p>Este gráfico no es una votación ni una promesa. Cada punto resume el juicio individual de un participante sobre el nivel apropiado de la tasa al cierre de cada año.</p><div id=\"fomcDotPlot\" class=\"dotplot\" aria-label=\"Proyecciones de tasas del FOMC de septiembre de 2026\"></div><p class=\"dot-source\">Datos de la <a href=\"https://www.federalreserve.gov/monetarypolicy/fomcprojtabl20260916.htm\" target=\"_blank\" rel=\"noopener\">Tabla oficial de Proyecciones Económicas de septiembre de 2026</a>. Se actualizará cuando el FOMC publique nuevas proyecciones.</p></div></div></article>`;\r\nconst lecturaPagina=$('lectura');\r\n(lecturaPagina||$('guide')).insertAdjacentElement('afterend',paginaPolitica);\r\nif(navegacionCompleta&&!navegacionCompleta.querySelector('[data-main-view=\"politica\"]')){const b=document.createElement('button');b.className='tab main-view';b.type='button';b.dataset.mainView='politica';b.setAttribute('aria-selected','false');b.textContent='POLÍTICA ECONÓMICA DE EE. UU.';navegacionCompleta.append(b)}\r\nfunction mostrarVistaPrincipal(nombre){$('dash').hidden=nombre!=='dash';$('guide').hidden=nombre!=='leer';$('lectura').hidden=nombre!=='lectura';paginaPolitica.hidden=nombre!=='politica';document.querySelectorAll('.main-view').forEach(x=>x.setAttribute('aria-selected',x.dataset.mainView===nombre));scrollTo({top:0,behavior:'smooth'})}\r\ndocument.querySelectorAll('.main-view').forEach(b=>b.onclick=()=>mostrarVistaPrincipal(b.dataset.mainView));\r\npaginaPolitica.querySelectorAll('.institution-nav button').forEach(b=>b.onclick=()=>{const oficina=b.dataset.office;paginaPolitica.querySelectorAll('.institution-nav button').forEach(x=>x.setAttribute('aria-selected',x===b));paginaPolitica.querySelectorAll('[data-office-detail]').forEach(x=>x.hidden=x.dataset.officeDetail!==oficina)});\r\nconst datosPuntos={2026:{'4.375':4,'4.125':12,'3.875':2},2027:{'4.375':8,'4.125':6,'3.625':3,'3.125':1},2028:{'4.125':4,'3.875':5,'3.625':3,'3.375':1,'3.125':4},2029:{'3.875':3,'3.625':7,'3.375':2,'3.125':4,'2.875':1},'Largo plazo':{'3.875':2,'3.750':1,'3.625':2,'3.500':2,'3.375':1,'3.250':2,'3.125':1,'3.000':6}};\r\nconst niveles=[4.5,4.375,4.25,4.125,4,3.875,3.75,3.625,3.5,3.375,3.25,3.125,3,2.875,2.75];\r\nconst nombres=Object.keys(datosPuntos),ancho=760,alto=355,izq=56,der=18,arriba=18,abajo=40;\r\nconst x=n=>izq+n*(ancho-izq-der)/(nombres.length-1),y=v=>arriba+(4.5-v)*(alto-arriba-abajo)/(4.5-2.75);\r\nlet grafico=`<svg viewBox=\"0 0 ${ancho} ${alto}\" role=\"img\" aria-label=\"Dot Plot del FOMC, septiembre de 2026\">`;\r\nniveles.forEach(v=>{grafico+=`<line class=\"gridline\" x1=\"${izq}\" x2=\"${ancho-der}\" y1=\"${y(v)}\" y2=\"${y(v)}\"/><text class=\"axis-label\" x=\"4\" y=\"${y(v)+4}\">${v.toFixed(3)}%</text>`});\r\nnombres.forEach((nombre,i)=>{grafico+=`<text class=\"year-label\" x=\"${x(i)}\" y=\"${alto-12}\" text-anchor=\"middle\">${nombre}</text>`;Object.entries(datosPuntos[nombre]).forEach(([nivel,cantidad])=>{for(let j=0;j<cantidad;j++){const desplazamiento=(j-(cantidad-1)/2)*7;grafico+=`<circle class=\"dot\" cx=\"${x(i)+desplazamiento}\" cy=\"${y(Number(nivel))}\" r=\"4.5\"><title>${nombre}: ${nivel}%</title></circle>`}})});\r\ngrafico+='</svg>';$('fomcDotPlot').innerHTML=grafico;\r\n</script><style>\r\n/* Consulta de probabilidades de mercado: FedWatch, en lugar del gráfico interno de proyecciones. */\r\n.fedwatch-frame{display:block;width:100%;height:620px;border:1px solid var(--l);background:var(--p);margin-top:14px}.fedwatch-note{border-left:4px solid var(--amber);background:var(--p2);padding:13px 15px;margin:13px 0 0;font-size:.9rem}.fedwatch-fallback{margin-top:12px;font-weight:700}.fedwatch-fallback a{color:var(--teal)}@media(max-width:760px){.fedwatch-frame{height:540px}}\r\n</style><script>\r\n/* CME FedWatch sustituye el dot plot como lectura principal de expectativas de tasas. */\r\nconst consultaFomc=$('politicaEconomica');\r\nconst panelProyecciones=consultaFomc?.querySelector('.fomc-consultation > div:nth-child(2)');\r\nif(panelProyecciones){\r\n  panelProyecciones.innerHTML=`<h3 style=\"font-family:Cambria,Georgia,serif;margin:0 0 8px\">Probabilidades de tasas implícitas en el mercado</h3><p>El CME FedWatch Tool estima las probabilidades de los resultados de próximas reuniones del FOMC a partir de precios de futuros de Fed Funds a 30 días.</p><iframe class=\"fedwatch-frame\" src=\"https://www.cmegroup.com/markets/interest-rates/cme-fedwatch-tool.html\" title=\"CME FedWatch Tool: probabilidades implícitas de tasas del FOMC\" loading=\"lazy\" referrerpolicy=\"strict-origin-when-cross-origin\">Tu navegador no puede mostrar esta consulta integrada.</iframe><p class=\"fedwatch-fallback\"><a href=\"https://www.cmegroup.com/markets/interest-rates/cme-fedwatch-tool.html\" target=\"_blank\" rel=\"noopener\">Abrir CME FedWatch Tool en una pestaña nueva</a></p><div class=\"fedwatch-note\"><b>Cómo leerlo:</b> muestra expectativas de participantes del mercado, no una decisión de la Reserva Federal ni una predicción garantizada. Las probabilidades cambian con los precios de futuros. Fuente y atribución: CME FedWatch.</div>`;\r\n}\r\n</script><style>\r\n/* Acceso externo claro cuando el proveedor no admite ser incorporado dentro de otra página. */\r\n.fedwatch-external{display:grid;place-items:center;min-height:250px;border:1px solid var(--l);background:var(--p2);padding:24px;text-align:center}.fedwatch-external h3{font-family:Cambria,Georgia,serif;font-size:1.35rem;margin:0 0 9px}.fedwatch-external p{max-width:52ch}.fedwatch-open{display:inline-block;margin-top:18px;padding:12px 16px;background:var(--teal);border:1px solid var(--teal);color:#fff!important;text-decoration:none;font-weight:750}.fedwatch-open:hover{background:transparent;color:var(--teal)!important}.fedwatch-caption{margin-top:14px;font-size:.83rem;color:var(--m)}\r\n</style><script>\r\n/* CME restringe la visualización dentro de iframes; se conserva la consulta oficial en una nueva pestaña. */\r\nconst panelFedWatch= $('politicaEconomica')?.querySelector('.fomc-consultation > div:nth-child(2)');\r\nif(panelFedWatch){panelFedWatch.innerHTML=`<div class=\"fedwatch-external\"><div><h3>Probabilidades de tasas: CME FedWatch</h3><p>Las probabilidades implícitas en futuros de Fed Funds se consultan directamente en CME FedWatch, donde se actualizan según el mercado.</p><a class=\"fedwatch-open\" href=\"https://www.cmegroup.com/markets/interest-rates/cme-fedwatch-tool.html\" target=\"_blank\" rel=\"noopener\">Abrir CME FedWatch Tool</a><p class=\"fedwatch-caption\">CME no permite mostrar su herramienta completa dentro de este tablero. Las probabilidades son expectativas de mercado, no decisiones confirmadas de la Reserva Federal.</p></div></div>`}\r\n</script><style>\r\n/* Academia: experiencia de aprendizaje separada del tablero gratuito. */\r\n.academy-page{max-width:1120px;margin:0 auto}.academy-page[hidden]{display:none}.academy-page .card{margin-bottom:18px}.academy-hero{display:grid;grid-template-columns:1.25fr .75fr;gap:24px;align-items:center;border-top:5px solid var(--teal);padding:27px!important}.academy-hero h2{font-family:Cambria,Georgia,serif;font-size:2.05rem;letter-spacing:-.03em;margin:0 0 10px}.academy-hero p{max-width:70ch}.academy-stats{display:grid;gap:9px}.academy-stat{border-left:3px solid var(--teal);padding:9px 0 9px 12px;background:var(--p2)}.academy-stat b{display:block;font-size:.98rem}.academy-stat span{font-size:.82rem;color:var(--m)}.academy-heading{display:flex;justify-content:space-between;gap:18px;align-items:end;margin-bottom:14px}.academy-heading h2{font-family:Cambria,Georgia,serif;font-size:1.45rem}.academy-heading p{max-width:620px}.course-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.course-card{border:1px solid var(--l);border-top:4px solid var(--teal);background:var(--p);padding:17px;min-height:222px;display:flex;flex-direction:column}.course-card.locked{border-top-color:#758b92;background:var(--p2)}.course-card h3{font-family:Cambria,Georgia,serif;font-size:1.14rem;margin:9px 0}.course-card p{font-size:.9rem}.course-tag{font-size:.73rem;font-weight:750;color:var(--teal);letter-spacing:.04em;text-transform:uppercase}.course-card.locked .course-tag{color:var(--m)}.course-card button{margin-top:auto;align-self:flex-start;border:1px solid var(--teal);background:transparent;color:var(--teal);padding:8px 10px;font:700 .82rem \"Segoe UI\",sans-serif;cursor:pointer}.course-card.locked button{border-color:var(--l);color:var(--m)}.lesson-layout{display:grid;grid-template-columns:1fr .82fr;gap:25px}.lesson-layout h2{font-family:Cambria,Georgia,serif;font-size:1.6rem;margin:0 0 9px}.lesson-layout h3{font-family:Cambria,Georgia,serif;font-size:1.15rem;margin:18px 0 7px}.lesson-layout p,.lesson-layout li{font-size:.97rem;line-height:1.68}.lesson-layout ul{padding-left:20px}.learning-callout{border-left:4px solid var(--amber);background:#fffaf0;padding:15px 17px;margin:16px 0}.quiz-box{border:1px solid var(--l);background:var(--p2);padding:18px}.quiz-box h3{margin-top:0}.quiz-choice{display:block;width:100%;text-align:left;border:1px solid var(--l);background:var(--p);color:var(--t);padding:10px 12px;margin-top:8px;font:inherit;cursor:pointer}.quiz-choice:hover{border-color:var(--teal)}.quiz-feedback{min-height:2.7em;margin-top:12px!important;font-weight:700}.academy-plan{border-top:4px solid var(--amber);padding:22px!important}.academy-plan h2{font-family:Cambria,Georgia,serif;font-size:1.4rem}.academy-plan ul{columns:2;padding-left:20px}.academy-plan li{margin:7px 0;color:var(--m)}.academy-plan .plan-note{border-left:3px solid var(--teal);padding:10px 12px;background:var(--p2);margin-top:15px}@media(max-width:820px){.academy-hero,.lesson-layout{grid-template-columns:1fr}.course-grid{grid-template-columns:1fr 1fr}.academy-plan ul{columns:1}}@media(max-width:560px){.course-grid{grid-template-columns:1fr}.academy-hero h2{font-size:1.65rem}}\r\nhtml[data-theme=\"dark\"] .learning-callout{background:#2d2617}.course-card.locked{background:#18282e}.quiz-box{background:#182a30}\r\n</style><script>\r\n/* Academia sin cobro todavía: contenido inicial abierto y estructura para una futura suscripción. */\r\nconst academia=document.createElement('section');\r\nacademia.id='academia';academia.className='academy-page';academia.hidden=true;\r\nacademia.innerHTML=`<article class=\"card academy-hero\"><div><p class=\"ey\">Aprendizaje aplicado</p><h2>Academia de Economía Aplicada</h2><p>Aprende a interpretar tasas, bonos, inflación, crédito y liquidez usando los indicadores públicos del Radar de Mercados. El tablero muestra datos; la Academia enseña cómo relacionarlos sin convertirlos en recomendaciones de inversión.</p></div><div class=\"academy-stats\"><div class=\"academy-stat\"><b>1 módulo abierto</b><span>Empieza con el circuito económico.</span></div><div class=\"academy-stat\"><b>5 rutas avanzadas</b><span>Disponibles con el futuro plan Academia.</span></div><div class=\"academy-stat\"><b>Microlecciones y práctica</b><span>Concepto, ejemplo, tablero y comprobación.</span></div></div></article><article class=\"card\"><div class=\"academy-heading\"><div><h2>Ruta de aprendizaje</h2><p>Las lecciones se organizan desde los fundamentos hasta la lectura integrada de mercados.</p></div></div><div class=\"course-grid\"><article class=\"course-card\"><span class=\"course-tag\">Módulo abierto · Nivel 1</span><h3>La economía como un circuito</h3><p>Hogares, empresas, bancos, gobierno y mercados: qué papel cumple cada uno y cómo se conectan.</p><button type=\"button\" id=\"openFreeLesson\">Empezar módulo</button></article><article class=\"course-card locked\"><span class=\"course-tag\">Plan Academia · Nivel 1</span><h3>Dinero, tasas y bonos</h3><p>Qué hace una subida de tasas, cómo funciona un bono y por qué cambia su rendimiento.</p><button type=\"button\" class=\"locked-course\">Ver contenido del plan</button></article><article class=\"course-card locked\"><span class=\"course-tag\">Plan Academia · Nivel 2</span><h3>Inflación, hogares y consumo</h3><p>Precios, energía, salarios y confianza: cómo puede cambiar el comportamiento de los hogares.</p><button type=\"button\" class=\"locked-course\">Ver contenido del plan</button></article><article class=\"course-card locked\"><span class=\"course-tag\">Plan Academia · Nivel 2</span><h3>Crédito, riesgo y mercados</h3><p>VIX, diferenciales de crédito y condiciones financieras explicados con casos prácticos.</p><button type=\"button\" class=\"locked-course\">Ver contenido del plan</button></article><article class=\"course-card locked\"><span class=\"course-tag\">Plan Academia · Nivel 3</span><h3>Liquidez y sistema bancario</h3><p>ON RRP, Cuenta General del Tesoro, Reservas Bancarias y el circuito de liquidez.</p><button type=\"button\" class=\"locked-course\">Ver contenido del plan</button></article><article class=\"course-card locked\"><span class=\"course-tag\">Plan Academia · Nivel 3</span><h3>Política económica y comercio</h3><p>Fed, Tesoro, Congreso, comercio, aranceles y por qué sus decisiones se transmiten con retraso.</p><button type=\"button\" class=\"locked-course\">Ver contenido del plan</button></article></div></article><article id=\"freeLesson\" class=\"card\"><div class=\"lesson-layout\"><div><p class=\"ey\">Módulo 1 · Lección 1</p><h2>La economía como un circuito</h2><p>Una economía no es una máquina con un único conductor. Es una red de decisiones conectadas: hogares consumen y trabajan; empresas producen e invierten; bancos conceden crédito; el gobierno recauda y gasta; los mercados asignan precios y financiación.</p><h3>El recorrido básico</h3><ul><li><b>Hogares:</b> reciben ingresos, consumen, ahorran y solicitan crédito.</li><li><b>Empresas:</b> contratan, producen, fijan precios e invierten.</li><li><b>Bancos y mercados:</b> transforman ahorro en crédito y financiamiento.</li><li><b>Gobierno:</b> recauda impuestos, realiza pagos y emite deuda.</li><li><b>Reserva Federal:</b> influye sobre condiciones monetarias y financieras.</li></ul><div class=\"learning-callout\"><b>Conexión con el tablero:</b> el Diésel aporta contexto de costes; el CPI, de precios; el Tesoro a 10 años, de financiación; el High Yield OAS y el VIX, de riesgo; las lecturas de liquidez muestran una parte de la infraestructura financiera.</div><p>La relación nunca es automática. Una subida de un coste puede tardar en afectar precios; una subida de tasas puede tardar en afectar crédito, inversión o empleo.</p></div><aside class=\"quiz-box\"><p class=\"ey\">Comprueba tu lectura</p><h3>Pregunta rápida</h3><p>Si el rendimiento del Tesoro a 10 años aumenta y se mantiene alto, ¿qué interpretación es más prudente?</p><button class=\"quiz-choice\" type=\"button\" data-answer=\"false\">La Reserva Federal obligatoriamente subirá tasas en la próxima reunión.</button><button class=\"quiz-choice\" type=\"button\" data-answer=\"true\">Las condiciones de financiación de largo plazo pueden ser más exigentes y conviene observar crédito, inflación y actividad.</button><button class=\"quiz-choice\" type=\"button\" data-answer=\"false\">La bolsa necesariamente caerá al día siguiente.</button><p id=\"quizFeedback\" class=\"quiz-feedback\" aria-live=\"polite\">Elige una respuesta para comprobarla.</p></aside></div></article><article class=\"card academy-plan\"><h2>Qué incluirá el Plan Academia</h2><ul><li>Lecciones completas organizadas por nivel.</li><li>Ejemplos vinculados a los indicadores reales del tablero.</li><li>Preguntas de comprensión y progreso guardado.</li><li>Rutas temáticas: tasas, bonos, inflación, crédito, liquidez y política económica.</li><li>Glosario técnico en español con el término inglés entre paréntesis.</li><li>Casos de lectura: cómo interpretar varias señales al mismo tiempo.</li></ul><div class=\"plan-note\"><b>Estado actual:</b> esta es la maqueta educativa inicial. Todavía no solicita datos personales, no crea cuentas y no procesa pagos. Esas funciones se añadirán solo cuando el contenido y las condiciones del plan estén definidos.</div></article>`;\r\nconst paginaPoliticaActual=$('politicaEconomica');\r\n(paginaPoliticaActual||$('guide')).insertAdjacentElement('afterend',academia);\r\nconst navAcademia=document.querySelector('nav.tabs');\r\nif(navAcademia&&!navAcademia.querySelector('[data-main-view=\"academia\"]')){const b=document.createElement('button');b.className='tab main-view';b.type='button';b.dataset.mainView='academia';b.setAttribute('aria-selected','false');b.textContent='ACADEMIA';navAcademia.append(b)}\r\nfunction mostrarVistaAcademia(nombre){$('dash').hidden=nombre!=='dash';$('guide').hidden=nombre!=='leer';$('lectura').hidden=nombre!=='lectura';$('politicaEconomica').hidden=nombre!=='politica';academia.hidden=nombre!=='academia';document.querySelectorAll('.main-view').forEach(x=>x.setAttribute('aria-selected',x.dataset.mainView===nombre));scrollTo({top:0,behavior:'smooth'})}\r\ndocument.querySelectorAll('.main-view').forEach(b=>b.onclick=()=>mostrarVistaAcademia(b.dataset.mainView));\r\n$('openFreeLesson').onclick=()=>$('freeLesson').scrollIntoView({behavior:'smooth',block:'start'});\r\nacademia.querySelectorAll('.quiz-choice').forEach(b=>b.onclick=()=>{$('quizFeedback').textContent=b.dataset.answer==='true'?'Correcto. El rendimiento a 10 años aporta contexto sobre financiación de largo plazo; debe compararse con otras señales antes de concluir algo.':'Aún no. Una sola lectura no permite asegurar una decisión de la Fed ni el comportamiento inmediato de la bolsa. Revisa la relación entre tasas, crédito, inflación y actividad.'});\r\nacademia.querySelectorAll('.locked-course').forEach(b=>b.onclick=()=>{const nota=academia.querySelector('.plan-note');nota.textContent='Este módulo formará parte del Plan Academia. Primero construiremos sus lecciones, ejercicios y ejemplos; la suscripción se activará después, no en esta etapa.';nota.scrollIntoView({behavior:'smooth',block:'center'})});\r\n</script></body></html>\r\n";
const consultorPage = "<!doctype html>\n<html lang=\"es\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Consultor Inteligente · Observatorio RM</title><style>\n:root{--bg:#edf6f5;--panel:#fff;--ink:#123139;--muted:#54727a;--line:#b8d4d1;--brand:#087e78;--warn:#a16207;--soft:#f4fbfa}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px system-ui,sans-serif}main{max-width:980px;margin:auto;padding:28px 18px 60px}.back{color:var(--brand);font-weight:750;text-decoration:none}.ey{font-size:.75rem;letter-spacing:.12em;font-weight:800;text-transform:uppercase;color:var(--brand)}h1{font-size:clamp(2rem,6vw,3.4rem);letter-spacing:-.055em;margin:.3rem 0}h2{margin:0 0 8px}p{color:var(--muted);line-height:1.6}.card{border:1px solid var(--line);border-radius:18px;background:var(--panel);padding:22px;margin:16px 0;box-shadow:0 8px 25px #16464c12}.search{display:flex;gap:10px;flex-wrap:wrap}.search input{flex:1;min-width:210px;border:1px solid var(--line);border-radius:10px;padding:13px;font:inherit;color:var(--ink);background:var(--panel)}button{border:0;border-radius:10px;background:var(--brand);color:white;padding:13px 17px;font:700 1rem system-ui;cursor:pointer}button:hover{filter:brightness(.92)}.hint{font-size:.86rem}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.metric{border:1px solid var(--line);border-radius:12px;padding:15px;background:var(--soft)}.metric b{display:block;font-size:1.38rem;margin:4px 0}.tag{display:inline-block;padding:4px 8px;border-radius:99px;background:#087e7814;color:var(--brand);font-weight:750;font-size:.75rem}.warn{border-left:4px solid #d18a00;background:#fff9e9;padding:13px 15px;border-radius:8px}.source{font-size:.88rem}.source a{color:var(--brand);font-weight:700}.result[hidden]{display:none}.facts{padding-left:20px}.facts li{margin:7px 0;color:var(--muted)}.tv-card{padding-bottom:14px}.tv-header{display:flex;gap:12px;align-items:baseline;justify-content:space-between;flex-wrap:wrap}.tv-frame{height:442px;margin-top:16px}.tradingview-widget-container{height:100%;width:100%}.tradingview-widget-container__widget{width:100%}.tradingview-widget-copyright{font-size:.78rem;color:var(--muted);padding-top:7px}.tradingview-widget-copyright a{color:var(--brand)}@media(max-width:650px){.grid{grid-template-columns:1fr}.tv-frame{height:390px}}@media(prefers-color-scheme:dark){:root{--bg:#102326;--panel:#173236;--ink:#e4f4f2;--muted:#b0c9c7;--line:#315b5d;--brand:#51c2b9;--soft:#1b3b3e}.warn{background:#493c1d;color:#fff4c7}}\n</style></head><body><main>\n<a class=\"back\" href=\"./index.html\">← Volver al Radar de Mercados</a>\n<p class=\"ey\" style=\"margin-top:28px\">Observatorio RM · revisión</p><h1>Consultor Inteligente de Activos</h1>\n<p>Consulta una serie macro, un emisor de EE. UU. o un criptoactivo. El informe separa datos observados, cálculos y límites; no da recomendaciones de inversión.</p>\n<section class=\"card\"><h2>Consultar</h2><form id=\"form\" class=\"search\"><input id=\"query\" maxlength=\"20\" autocomplete=\"off\" placeholder=\"Ej.: VIXCLS, DGS10, AAPL, SPY o BTC\" aria-label=\"Activo o serie\"><button>Analizar</button></form><p class=\"hint\">Series macro: VIXCLS, DGS10, SOFR, CPI, ICSA, NFCI, BAMLH0A0HYM2, RRPONTSYD, WTREGEN y WRESBAL. BTC consulta el par BTCUSDT de Binance Spot.</p></section>\n<section id=\"marketVisual\" class=\"card tv-card\" aria-live=\"polite\"></section>\n<section id=\"loading\" class=\"card\" hidden><p>Buscando datos públicos…</p></section><section id=\"result\" class=\"result\" aria-live=\"polite\"></section>\n<section class=\"card\"><h2>Cómo funciona esta versión</h2><ul class=\"facts\"><li><b>Macro:</b> usa el histórico público del Radar para las series FRED disponibles.</li><li><b>Corporativo:</b> consulta SEC EDGAR desde el servidor para datos XBRL y presentaciones oficiales.</li><li><b>Cripto:</b> BTC consulta la API pública documentada de Binance Spot; el precio corresponde a ese mercado y a una ventana móvil de 24 horas.</li><li><b>Acciones y ETF:</b> no se muestra cotización cuando no existe una licencia de datos autorizada para esta aplicación privada.</li></ul></section>\n<script>\nconst series={VIXCLS:{key:'vix',name:'VIX',unit:'puntos',source:'https://fred.stlouisfed.org/series/VIXCLS'},DGS10:{key:'treasury10y',name:'Treasury de EE. UU. a 10 años',unit:'%',source:'https://fred.stlouisfed.org/series/DGS10'},SOFR:{key:'sofr',name:'SOFR',unit:'%',source:'https://fred.stlouisfed.org/series/SOFR'},CPI:{key:'inflation',name:'Índice CPI',unit:'índice',source:'https://fred.stlouisfed.org/series/CPIAUCSL'},CPIAUCSL:{key:'inflation',name:'Índice CPI',unit:'índice',source:'https://fred.stlouisfed.org/series/CPIAUCSL'},ICSA:{key:'claims',name:'Solicitudes iniciales de desempleo',unit:'solicitudes',source:'https://fred.stlouisfed.org/series/ICSA'},NFCI:{key:'nfci',name:'Condiciones financieras nacionales',unit:'índice',source:'https://fred.stlouisfed.org/series/NFCI'},BAMLH0A0HYM2:{key:'credit',name:'High Yield OAS',unit:'%',source:'https://fred.stlouisfed.org/series/BAMLH0A0HYM2'},RRPONTSYD:{key:'rrp',name:'RRP overnight',unit:'millones USD',source:'https://fred.stlouisfed.org/series/RRPONTSYD'},WTREGEN:{key:'tga',name:'Cuenta General del Tesoro',unit:'millones USD',source:'https://fred.stlouisfed.org/series/WTREGEN'},WRESBAL:{key:'reserves',name:'Reservas bancarias',unit:'millones USD',source:'https://fred.stlouisfed.org/series/WRESBAL'}};\nconst $=x=>document.getElementById(x);let market;async function data(){if(market)return market;for(const url of ['./data/market.json','https://raw.githubusercontent.com/aplicacioneserusalver1188-bot/radar-de-mercados/main/data/market.json']){try{const r=await fetch(url,{cache:'no-store'});if(r.ok)return market=await r.json()}catch(e){}}throw Error('No fue posible leer el histórico público del Radar.')}function n(v){return new Intl.NumberFormat('es-VE',{maximumFractionDigits:2}).format(v)}function usageText(u){if(!u?.persistent)return 'Consumo mensual: contador no disponible.';if(!u.cap)return `Consumo de Wolfram en ${u.month}: ${u.used}. Sin cupo configurado; consulte su plan.`;return `Consumo de Wolfram en ${u.month}: ${u.used}/${u.cap} · restantes: ${Math.max(0,u.cap-u.used)}.`}\nfunction macro(code,meta){const p=(market.series[meta.key]?.points||[]).map(x=>({date:x.date,value:+x.value})).filter(x=>Number.isFinite(x.value));const last=p.at(-1),prev=p.at(-2);if(!last)throw Error('La serie no tiene observaciones disponibles.');const diff=last.value-prev.value,pct=prev.value?diff/prev.value*100:null;const expression=`((${last.value})-(${prev.value}))/(${prev.value})*100`;return `<article class=\"card\"><span class=\"tag\">Hecho observado · FRED</span><h2>${meta.name}</h2><p>Última observación publicada: <b>${last.date}</b>. La frecuencia y el retraso dependen de la serie.</p><div class=\"grid\"><div class=\"metric\"><small>Último valor</small><b>${n(last.value)} ${meta.unit}</b><small>Dato observado</small></div><div class=\"metric\"><small>Cambio vs. observación anterior</small><b>${diff>=0?'+':''}${n(diff)} ${meta.unit}</b><small>Cálculo local reproducible</small></div><div class=\"metric\"><small>Variación porcentual</small><b>${pct===null?'—':(pct>=0?'+':'')+n(pct)+'%'}</b><small>Cálculo local reproducible</small></div></div><p class=\"source\">Fuente: <a href=\"${meta.source}\" target=\"_blank\" rel=\"noopener\">serie ${code} en FRED</a>. Este producto usa datos de FRED, pero no está respaldado ni certificado por el Banco de la Reserva Federal de San Luis.</p><button type=\"button\" class=\"wolfram\" data-expression=\"${expression}\">Comprobar cálculo con Wolfram</button><p class=\"hint\" id=\"wolframResult\">Wolfram recibe únicamente la expresión numérica; no se almacena su respuesta.</p><div class=\"warn\"><b>Análisis:</b> el cambio describe dos observaciones consecutivas; por sí solo no explica causas ni predice precios.</div></article>`}\nfunction h(value){return String(value??'—').replace(/[&<>'\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',\"'\":'&#39;','\"':'&quot;'}[c]))}function usd(value){return typeof value==='number'?new Intl.NumberFormat('es-VE',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(value):'—'}\nasync function secAsset(code){const r=await fetch(`/api/sec?ticker=${encodeURIComponent(code)}`),d=await r.json();if(d.error)return `<article class=\"card warn\"><b>SEC EDGAR:</b> ${h(d.error)}</article>`;const facts=Object.values(d.fundamentals||{}).filter(Boolean).map(x=>`<div class=\"metric\"><small>${h(x.label)}</small><b>${usd(x.value)}</b><small>${h(x.form)} · período ${h(x.end)} · presentado ${h(x.filed)}</small></div>`).join('')||'<p>No se encontraron hechos XBRL comparables de ingresos, resultado, activos o pasivos.</p>';const filings=(d.filings||[]).map(x=>`<li><a href=\"${h(x.url||'https://www.sec.gov/edgar/search/')}\" target=\"_blank\" rel=\"noopener\">${h(x.form)} · ${h(x.filingDate)}</a>${x.reportDate?` · período ${h(x.reportDate)}`:''}${x.description?` · ${h(x.description)}`:''}</li>`).join('')||'<li>No hay 10-K, 10-Q ni 8-K recientes en el historial de este emisor.</li>';return `<article class=\"card\"><span class=\"tag\">Hechos observados · SEC EDGAR</span><h2>${h(d.name)} (${h(code)})</h2><p>CIK ${h(d.cik)}${d.sic?` · ${h(d.sic)}`:''}. Los importes son hechos XBRL reportados; no son cotizaciones.</p><div class=\"grid\">${facts}</div><h3>Presentaciones oficiales recientes</h3><ul class=\"facts\">${filings}</ul><p class=\"source\">Fuente: <a href=\"https://www.sec.gov/edgar/search/\" target=\"_blank\" rel=\"noopener\">SEC EDGAR</a>. Fecha de cada dato y período mostrados arriba.</p><div class=\"warn\"><b>Límite:</b> SEC no proporciona precio ni volumen de mercado. Un ETF puede usar formularios distintos de 10-K, 10-Q y 8-K.</div></article>`}\nasync function cryptoAsset(code){const pair=code==='BTC'?'BTCUSDT':code;const r=await fetch(`/api/binance?symbol=${encodeURIComponent(pair)}`),d=await r.json();if(d.error)return `<article class=\"card warn\"><b>Binance:</b> ${h(d.error)}</article>`;const stamp=new Date(Number(d.closeTime)).toLocaleString('es-VE');const unit=d.symbol.endsWith('USD')?'USD':'USDT';return `<article class=\"card\"><span class=\"tag\">Hecho observado · ${h(d.source)}</span><h2>${h(d.symbol)}</h2><p>Última estadística recibida: <b>${h(stamp)}</b>. La variación corresponde a una ventana móvil de 24 horas del mercado indicado, no a un índice global de criptoactivos.</p><div class=\"grid\"><div class=\"metric\"><small>Último precio</small><b>${h(d.price)} ${unit}</b><small>Dato observado</small></div><div class=\"metric\"><small>Variación 24 h</small><b>${Number(d.changePercent)>=0?'+':''}${h(d.changePercent)}%</b><small>${h(d.change)} ${unit}</small></div><div class=\"metric\"><small>Volumen 24 h</small><b>${n(Number(d.volume))} BTC</b><small>${n(Number(d.quoteVolume))} ${unit}</small></div></div><p class=\"source\">Fuente: <a href=\"https://developers.binance.com/en/docs/products/spot/rest-api\" target=\"_blank\" rel=\"noopener\">API oficial de Binance</a>.</p><div class=\"warn\"><b>Riesgo:</b> precio, liquidez y disponibilidad dependen del mercado y de la jurisdicción; no constituyen recomendación.</div></article>`}\nconst tvSymbols={AAPL:'NASDAQ:AAPL',BAC:'NYSE:BAC',SPY:'AMEX:SPY',MSFT:'NASDAQ:MSFT',NVDA:'NASDAQ:NVDA',TSLA:'NASDAQ:TSLA',QQQ:'NASDAQ:QQQ',XLB:'AMEX:XLB',DXY:'TVC:DXY',EURUSD:'FX:EURUSD',USDVES:'FX_IDC:USDVES',US10Y:'FRED:DGS10',NI225:'INDEX:NKY',BTC:'BINANCE:BTCUSDT',BTCUSD:'BINANCE:BTCUSDT',BTCUSDT:'BINANCE:BTCUSDT',ETH:'BINANCE:ETHUSDT',ETHUSD:'BINANCE:ETHUSDT',SOL:'BINANCE:SOLUSDT',XRP:'BINANCE:XRPUSDT',BNB:'BINANCE:BNBUSDT',ADA:'BINANCE:ADAUSDT',DOGE:'BINANCE:DOGEUSDT',SPX:'SP:SPX',NDX:'NASDAQ:NDX',DJI:'DJ:DJI',VIX:'CBOE:VIX','^GSPC':'SP:SPX','^NDX':'NASDAQ:NDX','^DJI':'DJ:DJI'};const fxCurrencies=new Set(['USD','EUR','JPY','GBP','CHF','CAD','AUD','NZD','MXN','BRL','CLP','COP','PEN','ARS','CNY','HKD','SGD','KRW','INR','ZAR','TRY','SEK','NOK','DKK','PLN','CZK','HUF','RON','ILS','AED','SAR','QAR','VES']);let tvRenderVersion=0;\nasync function resolveTradingViewSymbol(value){const code=String(value||'').trim().toUpperCase();if(/^[A-Z0-9._-]{1,16}:[A-Z0-9._-]{1,24}$/.test(code))return {symbol:code,label:code,manual:false};if(tvSymbols[code])return {symbol:tvSymbols[code],label:code,manual:false};if(/^[A-Z]{6}$/.test(code)&&fxCurrencies.has(code.slice(0,3))&&fxCurrencies.has(code.slice(3)))return {symbol:`FX:${code}`,label:code,manual:false};const ticker=code.replace(/[^A-Z0-9._-]/g,'');if(!ticker)return {symbol:'NASDAQ:AAPL',label:'AAPL',manual:true};try{const response=await fetch(`/api/tradingview-symbol?ticker=${encodeURIComponent(ticker)}`),data=await response.json();if(data.symbol)return {symbol:data.symbol,label:code,manual:false}}catch(error){}return {symbol:`NASDAQ:${ticker}`,label:code,manual:true}}\nfunction tradingViewPanel(resolution){const symbol=resolution.symbol,url=`https://www.tradingview.com/symbols/${symbol.replace(':','-')}/`;const help=resolution.manual?'No se confirmó automáticamente el mercado. Usa «Cambiar símbolo» dentro del gráfico para elegir el resultado oficial de TradingView.':'Visualización independiente; no alimenta cálculos.';return `<div class=\"tv-header\"><div><span class=\"tag\">Visualización de mercado · TradingView</span><h2>Gráfico de ${h(resolution.label)}</h2></div><p class=\"hint\">${help}</p></div><div class=\"tv-frame\"><div id=\"tv-chart\" class=\"tradingview-widget-container\"><div class=\"tradingview-widget-container__widget\" style=\"height:calc(100% - 32px);width:100%\"></div><div class=\"tradingview-widget-copyright\"><a href=\"${url}\" rel=\"noopener nofollow\" target=\"_blank\"><span class=\"blue-text\">${h(resolution.label)} chart</span></a><span class=\"trademark\"> by TradingView</span></div></div></div>`}\nfunction mountTradingView(resolution){const holder=$('tv-chart');if(!holder)return;const script=document.createElement('script');script.type='text/javascript';script.src='https://s3.tradingview.com/external-embedding/embed-widget-advanced-chart.js';script.async=true;script.innerHTML=JSON.stringify({autosize:true,symbol:resolution.symbol,interval:'D',timezone:'exchange',theme:matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light',style:'1',locale:'es',allow_symbol_change:true,calendar:false,withdateranges:true,hide_side_toolbar:true,save_image:false,details:false,hotlist:false,support_host:'https://www.tradingview.com'});holder.appendChild(script)}\nasync function renderTradingView(code){const panel=$('marketVisual'),version=++tvRenderVersion;panel.innerHTML='<div class=\"tv-header\"><div><span class=\"tag\">Visualización de mercado · TradingView</span><h2>Preparando gráfico</h2></div><p class=\"hint\">Resolviendo el mercado del símbolo…</p></div><div class=\"tv-frame\"></div>';const resolution=await resolveTradingViewSymbol(code);if(version!==tvRenderVersion)return;panel.innerHTML=tradingViewPanel(resolution);mountTradingView(resolution)}\nasync function asset(code){const upper=code.replace(/[^A-Z0-9.^-]/g,'');return upper==='BTC'||upper==='BTCUSDT'?cryptoAsset(upper):secAsset(upper)}\nrenderTradingView('AAPL');\n$('form').onsubmit=async e=>{e.preventDefault();const code=$('query').value.trim().toUpperCase();if(!code)return;if(!series[code])renderTradingView(code);$('loading').hidden=false;$('result').hidden=true;try{if(series[code]){await data();$('result').innerHTML=macro(code,series[code])}else $('result').innerHTML=await asset(code);$('result').hidden=false;const b=document.querySelector('.wolfram');if(b)b.onclick=async()=>{b.disabled=true;const out=$('wolframResult');out.textContent='Calculando con Wolfram…';try{const r=await fetch('/api/wolfram',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({expression:b.dataset.expression})}),j=await r.json();out.textContent=j.result?`Wolfram · ${j.title}: ${j.result}. ${usageText(j.usage)}`:(j.error||'No hubo resultado.')+(j.usage?` ${usageText(j.usage)}`:'')}catch(x){out.textContent='No se pudo contactar el motor matemático.'}finally{b.disabled=false}}}catch(err){$('result').innerHTML='<article class=\"card warn\">No se pudo completar la consulta. Intenta de nuevo más tarde.</article>';$('result').hidden=false}finally{$('loading').hidden=true}};\n</script></main></body></html>\n";
